// Mock Data for the Session Knowledge Tree
const SESSION_KNOWLEDGE_LIST = [
    {
        id: 'sk1',
        label: '大额转账风险提示',
        tags: [
            { label: '大额转账 意图推荐', type: 'INTENT', color: 'bg-orange-100 text-orange-700 border-orange-200' },
            { label: '已查阅', type: 'STATUS_VIEWED', color: 'bg-blue-50 text-blue-600 border-blue-100' },
            { label: '已采用', type: 'STATUS_ADOPTED', color: 'bg-green-50 text-green-600 border-green-100' }
        ],
        content: '根据人行及我行反洗钱规定，个人账户单笔转账超过5万元（或等值外币），需向客户进行防诈骗风险提示，确认收款人信息及转账用途。\n\n话术示例：“为了您的资金安全，请问您是否认识收款人？务必警惕网络刷单、杀猪盘等电信诈骗风险。”'
    },
    {
        id: 'sk2',
        label: '转账限额与手续费标准',
        tags: [
            { label: '用户搜索', type: 'SEARCH', color: 'bg-purple-50 text-purple-600 border-purple-100' },
            { label: '已查阅', type: 'STATUS_VIEWED', color: 'bg-blue-50 text-blue-600 border-blue-100' },
            { label: '已采用', type: 'STATUS_ADOPTED', color: 'bg-green-50 text-green-600 border-green-100' }
        ],
        content: '【手机银行渠道认证方式】\n\n1. 短信验证码认证：单笔限额 5万元，日累计限额 5万元。\n2. 人脸识别/U盾认证：单笔限额 50万元，日累计限额 100万元。\n\n【手续费】\n跨行转账：普通卡每笔 2元 + 0.5%；金卡及以上免手续费。'
    },
    {
        id: 'sk3',
        label: '电子回单打印指引',
        tags: [
            { label: '流程推荐', type: 'PROCESS', color: 'bg-indigo-50 text-indigo-600 border-indigo-100' },
            { label: '已查阅', type: 'STATUS_VIEWED', color: 'bg-blue-50 text-blue-600 border-blue-100' }
        ],
        content: '客户可在手机银行 APP 首页搜索“电子回单”，选择对应交易明细进行下载或发送至邮箱。柜面打印需携带身份证及银行卡。'
    }
];

const KnowledgeFlow: React.FC = () => {
  const [view, setView] = useState<'LIST' | 'DETAIL'>('LIST');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(165); // Start simulation at a specific time

  // Knowledge State
  const [selectedKnowledgeId, setSelectedKnowledgeId] = useState<string>(SESSION_KNOWLEDGE_LIST[0].id);

  // Filter State
  const [filters, setFilters] = useState({
    keyword: '',
    businessType: '',
    startTime: '',
    endTime: ''
  });
  const [visibleSessions, setVisibleSessions] = useState(MOCK_SESSIONS);

  const selectedSession = MOCK_SESSIONS.find(s => s.id === selectedId) || MOCK_SESSIONS[0];

  const transcript = [
    { 
      time: '14:30:10', 
      seconds: 165,
      speaker: 'CUST', 
      text: '我想转账5万元', 
      sysHit: {
        intent: '大额转账',
        knowledgeId: 'sk1'
      }
    },
    { 
      time: '14:30:15', 
      seconds: 170,
      speaker: 'AGENT', 
      text: '好的，女士。根据规定，超过5万元的转账我需要先为您进行风险提示。', 
    },
    { 
      time: '14:30:25', 
      seconds: 180,
      speaker: 'CUST', 
      text: '好的，你说吧。', 
    },
    { 
      time: '14:30:30', 
      seconds: 185,
      speaker: 'AGENT', 
      text: '请问您是否认识收款人？务必警惕电信诈骗风险...', 
      usedKnowledgeId: 'sk1'
    },
    { 
      time: '14:30:45', 
      seconds: 200,
      speaker: 'CUST', 
      text: '对了，手机银行转账限额是多少？', 
    },
    { 
      time: '14:30:48', 
      seconds: 203,
      speaker: 'AGENT', 
      text: '正在为您查询手机银行限额...', 
      sysHit: {
        intent: '限额查询',
        knowledgeId: 'sk2'
      }
    },
  ];

  const agentActions = [
    { time: '14:30:12', type: '推送', desc: '系统自动推送"大额转账风险提示"' },
    { time: '14:30:13', type: '点击', desc: '坐席查看了"大额转账风险提示"' },
    { time: '14:30:28', type: '搜索', desc: '坐席主动搜索"转账限额"' },
  ];

  // Simulation for player
  useEffect(() => {
    let interval: any;
    if (isPlaying) {
      interval = setInterval(() => {
        setCurrentTime(prev => (prev + 1) % 503); // 08:23 is 503s
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isPlaying]);

  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60).toString().padStart(2, '0');
    const s = (secs % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  };

  const handleTranscriptClick = (seconds: number) => {
    setCurrentTime(seconds);
    setIsPlaying(true);
  };

  const handleKnowledgeClick = (knowledgeId: string) => {
    setSelectedKnowledgeId(knowledgeId);
  };

  // Filter Handlers
  const handleSearch = () => {
    let results = MOCK_SESSIONS;

    if (filters.keyword) {
      const lowerKw = filters.keyword.toLowerCase();
      results = results.filter(s => 
        s.id.toLowerCase().includes(lowerKw) || 
        s.agent.includes(filters.keyword) ||
        s.cust.toLowerCase().includes(lowerKw)
      );
    }

    if (filters.businessType) {
      results = results.filter(s => s.business === filters.businessType);
    }

    if (filters.startTime) {
      results = results.filter(s => s.time >= filters.startTime);
    }

    if (filters.endTime) {
      results = results.filter(s => s.time <= filters.endTime);
    }

    setVisibleSessions(results);
  };

  const handleReset = () => {
    setFilters({
      keyword: '',
      businessType: '',
      startTime: '',
      endTime: ''
    });
    setVisibleSessions(MOCK_SESSIONS);
  };

  const selectedKnowledge = SESSION_KNOWLEDGE_LIST.find(k => k.id === selectedKnowledgeId);

  if (view === 'LIST') {
    return (
      <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-200 h-full flex flex-col">
        {/* Title */}
        <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
           <h2 className="text-xl font-bold text-slate-800">会话流水列表</h2>
        </div>

        {/* Filters Bar */}
        <div className="mb-6 bg-slate-50/50 p-4 rounded-lg border border-slate-100 grid grid-cols-12 gap-4 items-end">
           {/* Keyword Search */}
           <div className="col-span-3">
              <label className="block text-xs font-medium text-slate-500 mb-1.5 ml-1">呼叫ID / 坐席工号</label>
              <div className="relative">
                 <input 
                    type="text" 
                    value={filters.keyword}
                    onChange={(e) => setFilters({...filters, keyword: e.target.value})}
                    placeholder="输入ID搜索..." 
                    className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
                 />
                 <Search size={16} className="absolute left-3 top-2.5 text-slate-400"/>
              </div>
           </div>

           {/* Business Type Select */}
           <div className="col-span-2">
              <label className="block text-xs font-medium text-slate-500 mb-1.5 ml-1">业务类型</label>
              <select 
                 value={filters.businessType}
                 onChange={(e) => setFilters({...filters, businessType: e.target.value})}
                 className="w-full px-3 py-2 border border-slate-300 rounded text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white appearance-none"
              >
                 <option value="">全部类型</option>
                 <option value="行内转账">行内转账</option>
                 <option value="账单查询">账单查询</option>
                 <option value="挂失业务">挂失业务</option>
              </select>
           </div>

           {/* Time Range */}
           <div className="col-span-5">
              <label className="block text-xs font-medium text-slate-500 mb-1.5 ml-1">时间范围</label>
              <div className="flex items-center space-x-2">
                  <div className="relative flex-1">
                     <input 
                        type="datetime-local" 
                        value={filters.startTime}
                        onChange={(e) => setFilters({...filters, startTime: e.target.value})}
                        className="w-full pl-3 pr-2 py-2 border border-slate-300 rounded text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white text-slate-600"
                        placeholder="开始时间"
                     />
                  </div>
                  <span className="text-slate-400 text-sm">至</span>
                  <div className="relative flex-1">
                     <input 
                        type="datetime-local" 
                        value={filters.endTime}
                        onChange={(e) => setFilters({...filters, endTime: e.target.value})}
                        className="w-full pl-3 pr-2 py-2 border border-slate-300 rounded text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white text-slate-600"
                        placeholder="结束时间"
                     />
                  </div>
              </div>
           </div>

           {/* Action Buttons */}
           <div className="col-span-2 flex space-x-2">
              <button 
                 onClick={handleSearch}
                 className="flex-1 bg-blue-600 hover:bg-blue-700 text-white py-2 px-4 rounded text-sm font-medium transition-colors flex items-center justify-center shadow-sm"
              >
                 <Search size={14} className="mr-1.5" />
                 查询
              </button>
              <button 
                 onClick={handleReset}
                 className="flex-1 bg-white hover:bg-slate-50 text-slate-600 border border-slate-300 py-2 px-4 rounded text-sm font-medium transition-colors flex items-center justify-center"
              >
                 <RotateCcw size={14} className="mr-1.5" />
                 重置
              </button>
           </div>
        </div>

        {/* Table */}
        <div className="flex-1 overflow-auto border rounded border-slate-200">
          <table className="w-full text-sm text-left text-slate-600">
             <thead className="bg-slate-50 text-slate-700 font-semibold sticky top-0">
               <tr>
                 <th className="px-6 py-3 border-b">呼叫ID</th>
                 <th className="px-6 py-3 border-b">坐席</th>
                 <th className="px-6 py-3 border-b">客户ID</th>
                 <th className="px-6 py-3 border-b">业务类型</th>
                 <th className="px-6 py-3 border-b">来电时间</th>
                 <th className="px-6 py-3 border-b">结束时间</th>
                 <th className="px-6 py-3 border-b">服务时长</th>
                 <th className="px-6 py-3 border-b">知识命中数</th>
                 <th className="px-6 py-3 border-b">知识采纳数</th>
                 <th className="px-6 py-3 border-b text-right">操作</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {visibleSessions.length > 0 ? (
                 visibleSessions.map(row => (
                 <tr key={row.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 font-mono text-xs">{row.id}</td>
                    <td className="px-6 py-4">{row.agent}</td>
                    <td className="px-6 py-4 font-mono text-xs">{row.cust}</td>
                    <td className="px-6 py-4"><span className="bg-blue-50 text-blue-700 px-2 py-1 rounded text-xs">{row.business}</span></td>
                    <td className="px-6 py-4">{row.time}</td>
                    <td className="px-6 py-4">{row.endTime}</td>
                    <td className="px-6 py-4">{row.duration}</td>
                    <td className="px-6 py-4">
                        <span className="flex items-center text-slate-600 font-medium"><Lightbulb size={14} className="mr-1 fill-slate-200"/> {row.hits}</span>
                    </td>
                    <td className="px-6 py-4">
                        <span className="flex items-center text-green-600 font-medium"><CheckCircle size={14} className="mr-1"/> {row.adoptions}</span>
                    </td>
                    <td className="px-6 py-4 text-right">
                       <button 
                         onClick={() => { setSelectedId(row.id); setView('DETAIL'); }}
                         className="text-blue-600 hover:text-blue-800 font-medium text-xs"
                       >
                         查看详情
                       </button>
                    </td>
                 </tr>
               ))
              ) : (
                <tr>
                  <td colSpan={10} className="px-6 py-12 text-center text-slate-400">
                    <div className="flex flex-col items-center">
                       <Search size={32} className="text-slate-300 mb-2" />
                       <p>未找到符合条件的会话记录</p>
                    </div>
                  </td>
                </tr>
              )}
             </tbody>
          </table>
        </div>
      </div>
    );
  }

  // DETAIL VIEW
  return (
    <div className="flex flex-col h-full space-y-3">
       {/* Top: Basic Info & Player */}
       <div className="bg-white p-3 rounded-lg shadow-sm border border-slate-200 flex flex-col space-y-3">
          <div className="flex items-center justify-between border-b pb-2 border-slate-100">
             <div className="flex items-center space-x-6 text-sm">
                <button onClick={() => setView('LIST')} className="text-slate-500 hover:text-slate-700 font-medium flex items-center transition-colors">
                   <ChevronRight size={16} className="rotate-180 mr-1"/> 返回列表
                </button>
                <div className="h-4 w-px bg-slate-200"></div>
                <div className="flex items-center space-x-2">
                    <Phone size={14} className="text-slate-400"/> 
                    <span className="text-slate-500">呼叫ID:</span>
                    <span className="font-mono font-medium">{selectedSession.id}</span>
                </div>
                <div className="flex items-center space-x-2">
                    <User size={14} className="text-slate-400"/>
                    <span className="text-slate-500">坐席:</span>
                    <span className="font-medium">{selectedSession.agent.split(' ')[0]}</span>
                </div>
                <div className="flex items-center space-x-2">
                    <SquareUser size={14} className="text-slate-400"/>
                    <span className="text-slate-500">客户ID:</span>
                    <span className="font-mono font-medium">{selectedSession.cust}</span>
                </div>
                <div className="flex items-center space-x-2">
                    <Calendar size={14} className="text-slate-400"/>
                    <span className="text-slate-500">来电时间:</span>
                    <span className="font-mono font-medium">{selectedSession.time}</span>
                </div>
             </div>
             <div className="flex space-x-2">
                <button className="px-3 py-1 border border-slate-300 rounded text-xs hover:bg-slate-50 transition-colors">下载录音</button>
                <button className="px-3 py-1 border border-slate-300 rounded text-xs hover:bg-slate-50 transition-colors">下载文本</button>
             </div>
          </div>

          <div className="flex space-x-4">
             {/* Player Section - Flex-1 */}
             <div className="flex-1 bg-slate-50 rounded px-4 py-2 flex items-center space-x-4 border border-slate-100">
                 <button 
                    onClick={() => setIsPlaying(!isPlaying)}
                    className="w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center text-white hover:bg-blue-700 transition-colors shadow-sm"
                 >
                    {isPlaying ? <Pause size={14} className="fill-current" /> : <Play size={14} className="ml-1 fill-current"/>}
                 </button>
                 <div className="flex-1">
                    <div className="h-1.5 bg-slate-200 rounded-full overflow-hidden cursor-pointer">
                       <div 
                          className="h-full bg-blue-500 rounded-full transition-all duration-300" 
                          style={{ width: `${(currentTime / 503) * 100}%` }}
                       ></div>
                    </div>
                    <div className="flex justify-between text-[10px] text-slate-400 mt-1 font-mono">
                       <span>{formatTime(currentTime)}</span>
                       <span>{selectedSession.duration}</span>
                    </div>
                 </div>
                 <Volume2 size={16} className="text-slate-400 cursor-pointer hover:text-slate-600"/>
             </div>

             {/* Follow-up Data Section */}
             <div className="flex space-x-2 text-xs">
                <div className="bg-blue-50/50 px-3 py-2 rounded border border-blue-100 flex flex-col justify-center min-w-[100px]">
                   <div className="text-blue-500 mb-0.5 flex items-center text-[10px]"><Shield size={10} className="mr-1"/> 客户等级</div>
                   <div className="font-bold text-blue-800 truncate">{selectedSession.level}</div>
                </div>
                <div className="bg-purple-50/50 px-3 py-2 rounded border border-purple-100 flex flex-col justify-center min-w-[100px]">
                   <div className="text-purple-500 mb-0.5 flex items-center text-[10px]"><Filter size={10} className="mr-1"/> 业务类型</div>
                   <div className="font-bold text-purple-800 truncate">{selectedSession.business}</div>
                </div>
                <div className="bg-slate-50 px-3 py-2 rounded border border-slate-200 flex flex-col justify-center min-w-[160px]">
                   <div className="text-slate-500 mb-0.5 flex items-center text-[10px]"><GitBranch size={10} className="mr-1"/> IVR路径</div>
                   <div className="font-semibold text-slate-700 truncate" title={selectedSession.ivr}>{selectedSession.ivr.split('>').pop()?.trim()}...</div>
                </div>
             </div>
          </div>
       </div>

       {/* Bottom: Transcript & Analysis - Expanded Height */}
       <div className="flex-1 grid grid-cols-12 gap-4 min-h-0">

          {/* Left: Transcript */}
          <div className="col-span-7 bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col overflow-hidden">
             <div className="p-3 border-b border-slate-100 bg-slate-50 font-medium text-sm text-slate-700 flex justify-between items-center">
                <span>对话文本</span>
                <span className="text-xs text-slate-400 font-normal">点击文本可跳转录音进度</span>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-6">
                {transcript.map((msg, idx) => (
                   <div key={idx} className="flex flex-col space-y-2">
                      <div className={`flex ${msg.speaker === 'AGENT' ? 'justify-end' : 'justify-start'}`}>
                         <div className="flex flex-col max-w-[85%]">
                             <div className={`text-[10px] text-slate-400 mb-1 flex items-center ${msg.speaker === 'AGENT' ? 'justify-end' : 'justify-start'}`}>
                                <span>{msg.speaker === 'AGENT' ? '坐席' : '客户'}</span>
                                <span className="mx-1">·</span>
                                <span className="font-mono">{msg.time}</span>
                             </div>
                             <div 
                                onClick={() => handleTranscriptClick(msg.seconds)}
                                className={`rounded-lg p-3 text-sm relative group cursor-pointer transition-colors shadow-sm
                                   ${msg.speaker === 'AGENT' 
                                      ? 'bg-blue-50 text-slate-800 rounded-tr-none hover:bg-blue-100' 
                                      : 'bg-slate-100 text-slate-800 rounded-tl-none hover:bg-slate-200'}`}
                             >
                                {msg.text}
                                {msg.speaker === 'AGENT' && msg.usedKnowledgeId && (
                                    <div 
                                      onClick={(e) => { e.stopPropagation(); handleKnowledgeClick(msg.usedKnowledgeId!); }}
                                      className="mt-2 pt-2 border-t border-blue-100/50 flex items-center text-[10px] text-green-700 cursor-pointer hover:text-green-800"
                                    >
                                       <CheckCircle size={10} className="mr-1"/> 
                                       已引用知识: {SESSION_KNOWLEDGE_LIST.find(k => k.id === msg.usedKnowledgeId)?.label}
                                    </div>
                                )}
                             </div>
                         </div>
                      </div>

                      {/* System Hit Info */}
                      {msg.sysHit && (
                         <div className="flex justify-center my-1">
                            <div className="bg-orange-50 border border-orange-100 rounded-full px-3 py-1 flex items-center space-x-3 shadow-sm transform hover:scale-105 transition-transform cursor-default">
                               <div className="flex items-center text-xs text-orange-700">
                                  <Lightbulb size={12} className="mr-1 fill-orange-200"/>
                                  <span className="opacity-70 mr-1">系统命中:</span>
                                  <span className="font-semibold">{msg.sysHit.intent}</span>
                               </div>
                            </div>
                         </div>
                      )}
                   </div>
                ))}
             </div>
          </div>

          {/* Right: Agent Behavior & Knowledge */}
          <div className="col-span-5 flex flex-col space-y-4 min-h-0">

              {/* Agent Actions Timeline */}
              <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col overflow-hidden h-[35%]">
                 <div className="p-3 border-b border-slate-100 bg-slate-50 font-medium text-sm text-slate-700">坐席行为追踪</div>
                 <div className="flex-1 overflow-y-auto p-4">
                    <div className="ml-2 relative border-l border-slate-200 space-y-6 my-2">
                        {agentActions.map((action, idx) => (
                           <div key={idx} className="relative pl-6">
                              {/* Dot */}
