                           </div>
                        )}
                    </div>
                 </div>
              </div>

          </div>
       </div>
    </div>
  );
};

export default KnowledgeFlow;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Intent, Slot, FormMode } from '../types';
import { Plus, Search, ChevronLeft, ToggleLeft, ToggleRight, X, HelpCircle, ChevronDown, Check, ChevronRight, Folder, Edit2, Trash2, Hash, Download, Upload, FileText, Activity, Play, RotateCcw, AlertCircle, CheckCircle, Rocket, Users, Clock, ShieldCheck, BarChart3, AlertTriangle, XCircle, Sparkles, Code } from 'lucide-react';
import { INTENT_CATEGORIES } from '../constants';

interface Props {
  intents: Intent[];
  setIntents: React.Dispatch<React.SetStateAction<Intent[]>>;
  slots: Slot[];
}

// Helper types for the category tree
interface CategoryNode {
  id: string;
  name: string;
  description?: string; // New: Category Description
  children: CategoryNode[];
  isExpanded?: boolean;
}

// Helper type for Training Versions
interface TrainingVersion {
    id: string;
    version: string;
    createTime: string;
    status: 'SUCCESS' | 'FAILED' | 'TRAINING';
    accuracy: number;
    slotAccuracy: number;
    datasetSize: number;
    epochs: number;
    description: string;
}

const IntentManager: React.FC<Props> = ({ intents, setIntents, slots }) => {
  // Mode now includes TRAINING
  const [mode, setMode] = useState<FormMode | 'TRAINING'>('LIST');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Training State
  const [trainingIntent, setTrainingIntent] = useState<Intent | null>(null);
  const [isTraining, setIsTraining] = useState(false);
  const [trainingProgress, setTrainingProgress] = useState(0);
  const [trainingVersions, setTrainingVersions] = useState<TrainingVersion[]>([
      { id: 'v1', version: 'V1.0.0', createTime: '2023-10-28 10:00:00', status: 'SUCCESS', accuracy: 85.5, slotAccuracy: 80.2, datasetSize: 200, epochs: 50, description: '初始版本' }
  ]);
  const [trainingEpochs, setTrainingEpochs] = useState(50);
  const [trainingLR, setTrainingLR] = useState(0.001);

  // --- Canary Release State ---
  const [showCanaryModal, setShowCanaryModal] = useState(false);
  const [canaryStep, setCanaryStep] = useState<'CONFIG' | 'MONITOR'>('CONFIG');
  const [canaryConfig, setCanaryConfig] = useState({
    scopeType: 'GROUP', // GROUP, AGENT, LINE
    scopeValue: '信用卡客服一组',
    duration: 24
  });
  // Mock Monitor Stats
  const [canaryStats, setCanaryStats] = useState({
    accuracy: 95.1,
    slotAccuracy: 92.0,
    totalRequests: 0,
    errorRate: 0.2
  });

  // Simulate Canary Stats Updates
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (showCanaryModal && canaryStep === 'MONITOR') {
      interval = setInterval(() => {
        setCanaryStats(prev => ({
          accuracy: Math.min(99.9, Math.max(90, prev.accuracy + (Math.random() - 0.4) * 0.2)),
          slotAccuracy: Math.min(99.9, Math.max(88, prev.slotAccuracy + (Math.random() - 0.4) * 0.2)),
          totalRequests: prev.totalRequests + Math.floor(Math.random() * 8) + 1,
          errorRate: Math.max(0, prev.errorRate + (Math.random() - 0.5) * 0.02)
        }));
      }, 1500);
    }
    return () => clearInterval(interval);
  }, [showCanaryModal, canaryStep]);


  // --- Category Management State ---
  const [categories, setCategories] = useState<CategoryNode[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  // Initialize categories
  useEffect(() => {
    const initialTree: CategoryNode[] = [];
    const map = new Map<string, CategoryNode>();

    INTENT_CATEGORIES.forEach(catStr => {
      const parts = catStr.split('/');
      const rootName = parts[0];

      if (!map.has(rootName)) {
        const newNode: CategoryNode = { id: rootName, name: rootName, description: '系统预置一级分类', children: [], isExpanded: true };
        map.set(rootName, newNode);
        initialTree.push(newNode);
      }

      if (parts.length > 1) {
        const root = map.get(rootName)!;
        const childName = parts[1];
        if (!root.children.find(c => c.name === childName)) {
            root.children.push({ id: `${rootName}/${childName}`, name: childName, description: '系统预置二级分类', children: [] });
        }
      }
    });
    setCategories(initialTree);
  }, []);

  // Category Modal State
  const [showCategoryModal, setShowCategoryModal] = useState(false);
  const [categoryModalMode, setCategoryModalMode] = useState<'ADD_ROOT' | 'ADD_SUB' | 'EDIT'>('ADD_ROOT');
  const [categoryModalTarget, setCategoryModalTarget] = useState<CategoryNode | null>(null);
  const [categoryInputName, setCategoryInputName] = useState('');
  const [categoryInputDesc, setCategoryInputDesc] = useState(''); // New Description Input

  // --- Intent Form Data ---
  const [formData, setFormData] = useState<Partial<Intent>>({
    name: '',
    category: '',
    description: '',
    slotIds: [],
    utterances: [],
    recognitionType: 'SEMANTIC',
    status: 'ACTIVE'
  });

  const [utteranceInput, setUtteranceInput] = useState('');

  // Slot Dropdown State
  const [isSlotDropdownOpen, setIsSlotDropdownOpen] = useState(false);
  const [slotSearchQuery, setSlotSearchQuery] = useState('');

  // --- Actions ---

  const handleEdit = (intent: Intent) => {
    setEditingId(intent.id);
    setFormData(intent);
    setMode('EDIT');
    setIsSlotDropdownOpen(false);
    setSlotSearchQuery('');
  };

  const handleTraining = (intent: Intent) => {
      setTrainingIntent(intent);
      // Reset training state specific to this session
      setTrainingProgress(0);
      setIsTraining(false);
      setMode('TRAINING');
  };

  const handleDelete = (id: string) => {
    if (confirm('确定删除该意图吗？')) {
      setIntents(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleSave = () => {
    if (!formData.name || !formData.category) {
      alert('请填写名称和分类');
      return;
    }

    if (mode === 'CREATE') {
      const newIntent: Intent = {
        id: `INT${Date.now().toString().slice(-6)}`,
        name: formData.name!,
        category: formData.category!,
        description: formData.description || '',
        slotIds: formData.slotIds || [],
        utterances: formData.utterances || [],
        recognitionType: formData.recognitionType || 'SEMANTIC',
        status: formData.status || 'ACTIVE',
        createTime: new Date().toLocaleString()
      };
      setIntents([...intents, newIntent]);
    } else if (mode === 'EDIT' && editingId) {
      setIntents(prev => prev.map(i => i.id === editingId ? { ...i, ...formData } as Intent : i));
    }

    setMode('LIST');
    setEditingId(null);
    setFormData({ name: '', category: '', description: '', slotIds: [], utterances: [], recognitionType: 'SEMANTIC', status: 'ACTIVE' });
  };

  // --- Import / Export Logic ---
  const handleExport = () => {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(intents, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", "bank_intents_export.json");
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const handleDownloadTemplate = () => {
      const template = [
          {
              "name": "示例意图",
              "category": "账户/示例",
              "utterances": ["怎么办理"],
              "slots": ["卡号"],
              "recognitionType": "SEMANTIC"
          }
      ];
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(template, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", "intent_import_template.json");
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const handleImportClick = () => {
      document.getElementById('intent-import-input')?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          alert(`成功导入文件: ${e.target.files[0].name}。包含 5 条新意图。`);
          // Mock import logic
      }
  };


  // --- Form Logic ---
  const addUtterance = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && utteranceInput.trim()) {
      e.preventDefault();
      setFormData(prev => ({
        ...prev,
        utterances: [...(prev.utterances || []), utteranceInput.trim()]
      }));
      setUtteranceInput('');
    }
  };

  const removeUtterance = (index: number) => {
    setFormData(prev => ({
      ...prev,
      utterances: prev.utterances?.filter((_, i) => i !== index)
    }));
  };

  const toggleSlot = (slotId: string) => {
    const currentSlots = formData.slotIds || [];
    if (currentSlots.includes(slotId)) {
      setFormData({ ...formData, slotIds: currentSlots.filter(id => id !== slotId) });
    } else {
      setFormData({ ...formData, slotIds: [...currentSlots, slotId] });
    }
  };

  // --- Category Logic ---

  const toggleExpand = (e: React.MouseEvent, nodeName: string) => {
    e.stopPropagation();
    setCategories(prev => prev.map(node => 
      node.name === nodeName ? { ...node, isExpanded: !node.isExpanded } : node
    ));
  };

  const getCategoryCount = (path: string) => {
    return intents.filter(i => {
       if (path.includes('/')) {
           return i.category === path;
       }
       return i.category.startsWith(path + '/') || i.category === path;
    }).length;
  };

  const openCategoryModal = (mode: 'ADD_ROOT' | 'ADD_SUB' | 'EDIT', target: CategoryNode | null = null) => {
    setCategoryModalMode(mode);
    setCategoryModalTarget(target);
    setCategoryInputName(mode === 'EDIT' && target ? target.name : '');
    setCategoryInputDesc(mode === 'EDIT' && target ? target.description || '' : '');
    setShowCategoryModal(true);
  };

  const handleCategorySave = () => {
    if (!categoryInputName.trim()) {
      alert('请输入分类名称');
      return;
    }

    const newDesc = categoryInputDesc.trim();

    if (categoryModalMode === 'ADD_ROOT') {
       if (categories.some(c => c.name === categoryInputName)) {
           alert('该一级分类已存在');
           return;
       }
       setCategories([...categories, { id: categoryInputName, name: categoryInputName, description: newDesc, children: [], isExpanded: true }]);
    } else if (categoryModalMode === 'ADD_SUB' && categoryModalTarget) {
       const updated = categories.map(cat => {
           if (cat.name === categoryModalTarget.name) {
               if (cat.children.some(c => c.name === categoryInputName)) return cat; 
               return {
                   ...cat,
                   children: [...cat.children, { id: `${cat.name}/${categoryInputName}`, name: categoryInputName, description: newDesc, children: [] }],
                   isExpanded: true
               };
           }
           return cat;
       });
       setCategories(updated);
    } else if (categoryModalMode === 'EDIT' && categoryModalTarget) {
       const oldPath = categoryModalTarget.id;
       const isRoot = !oldPath.includes('/');

       const updatedCats = categories.map(cat => {
           if (isRoot) {
               if (cat.name === categoryModalTarget.name) {
                   return { 
                       ...cat, 
                       name: categoryInputName,
                       description: newDesc,
                       id: categoryInputName,
                       children: cat.children.map(child => ({ ...child, id: `${categoryInputName}/${child.name}` })) 
                   };
               }
               return cat;
           } else {
               const parentName = oldPath.split('/')[0];
               if (cat.name === parentName) {
                   return {
                       ...cat,
                       children: cat.children.map(child => {
                           if (child.id === oldPath) {
                               return { ...child, name: categoryInputName, description: newDesc, id: `${parentName}/${categoryInputName}` };
                           }
                           return child;
                       })
                   }
               }
               return cat;
           }
       });
       setCategories(updatedCats);

       // Update Intents
       const newPath = isRoot ? categoryInputName : `${oldPath.split('/')[0]}/${categoryInputName}`;
       setIntents(prev => prev.map(intent => {
           if (isRoot) {
               if (intent.category.startsWith(oldPath + '/')) {
                   return { ...intent, category: intent.category.replace(oldPath, newPath) };
               }
           } else {
               if (intent.category === oldPath) {
                   return { ...intent, category: newPath };
               }
           }
           return intent;
       }));
    }

    setShowCategoryModal(false);
  };

  const deleteCategory = (node: CategoryNode) => {
    const isRoot = !node.id.includes('/');
    const count = getCategoryCount(node.id);

    if (confirm(`确定要删除分类 "${node.name}" 吗？\n该分类下有 ${count} 个意图，删除后意图将变为"未分类"。`)) {
        if (isRoot) {
            setCategories(prev => prev.filter(c => c.name !== node.name));
        } else {
            const parentName = node.id.split('/')[0];
            setCategories(prev => prev.map(c => {
                if (c.name === parentName) {
                    return { ...c, children: c.children.filter(child => child.id !== node.id) };
                }
                return c;
            }));
        }

        setIntents(prev => prev.map(intent => {
            const match = isRoot ? intent.category.startsWith(node.id + '/') : intent.category === node.id;
            if (match) {
                return { ...intent, category: '' };
            }
            return intent;
        }));

        if (selectedCategory === node.id || (isRoot && selectedCategory?.startsWith(node.id))) {
            setSelectedCategory(null);
        }
    }
  };

  // --- Start Training Simulation ---
  const startTrainingTask = () => {
      setIsTraining(true);
      setTrainingProgress(0);

      const interval = setInterval(() => {
          setTrainingProgress(prev => {
              if (prev >= 100) {
                  clearInterval(interval);
                  setIsTraining(false);
                  // Add new version
                  const newVer: TrainingVersion = {
                      id: `v${trainingVersions.length + 1}`,
                      version: `V1.${trainingVersions.length}.0`,
                      createTime: new Date().toLocaleString(),
                      status: 'SUCCESS',
                      accuracy: 95.2, // Improved
                      slotAccuracy: 92.1, // Improved
                      datasetSize: 500,
                      epochs: trainingEpochs,
                      description: '迭代优化'
                  };
                  setTrainingVersions(prevVer => [newVer, ...prevVer]);
                  return 100;
              }
              return prev + 5; // increment
          });
      }, 100);
  };

  // --- Canary Handlers ---
  const handleStartCanary = () => {
    setCanaryStep('MONITOR');
    // Reset stats for new run
    setCanaryStats({ accuracy: 95.1, slotAccuracy: 92.0, totalRequests: 0, errorRate: 0.0 });
  };

  const handleEndCanary = (type: 'FULL' | 'ROLLBACK') => {
      if (type === 'FULL') {
          alert('操作成功：新模型已全量发布，覆盖所有座席。');
      } else {
          alert('操作成功：灰度已终止，系统回滚至上一稳定版本。');
      }
      setShowCanaryModal(false);
      setCanaryStep('CONFIG');
  };

  // --- Filtering ---
  const filteredSlots = slots.filter(s => 
    s.name.toLowerCase().includes(slotSearchQuery.toLowerCase()) || 
    s.description?.toLowerCase().includes(slotSearchQuery.toLowerCase())
  );

  const filteredIntents = useMemo(() => {
      let result = intents;
      if (selectedCategory) {
          result = result.filter(i => {
              if (selectedCategory.includes('/')) return i.category === selectedCategory;
              return i.category.startsWith(selectedCategory + '/') || i.category === selectedCategory;
          });
      }
      return result;
  }, [intents, selectedCategory]);


  // --- VIEW: LIST ---
  if (mode === 'LIST') {
    return (
      <div className="bg-white rounded-lg shadow-sm border border-slate-200 h-full flex flex-col overflow-hidden">
        {/* Hidden Input for Import */}
        <input type="file" id="intent-import-input" className="hidden" accept=".json" onChange={handleFileChange} />

        {/* Header Section */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white flex-shrink-0">
           <div className="flex items-center">
                <h2 className="text-xl font-bold text-slate-800 mr-2">意图管理</h2>
                <div className="relative group cursor-help">
                    <HelpCircle size={18} className="text-slate-400 hover:text-blue-500 transition-colors" />
                    <div className="absolute left-full top-1/2 -translate-y-1/2 ml-2 w-80 p-3 bg-slate-800 text-white text-xs rounded shadow-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-50 leading-relaxed pointer-events-none">
                        关联槽位，定义用户的核心需求，完成业务流程的入口配置
                        <div className="absolute left-0 top-1/2 -translate-y-1/2 -ml-1 border-4 border-transparent border-r-slate-800"></div>
                    </div>
                </div>
           </div>

           <div className="flex space-x-3">
              {/* Import/Export Buttons */}
              <div className="flex space-x-1 mr-2 border-r border-slate-200 pr-3">
                  <button onClick={handleDownloadTemplate} className="flex items-center px-3 py-2 bg-slate-50 text-slate-600 rounded text-sm hover:bg-slate-100 border border-slate-200">
                      <FileText size={14} className="mr-2" />
                      下载模版
                  </button>
                  <button onClick={handleImportClick} className="flex items-center px-3 py-2 bg-slate-50 text-slate-600 rounded text-sm hover:bg-slate-100 border border-slate-200">
                      <Upload size={14} className="mr-2" />
                      导入
                  </button>
                  <button onClick={handleExport} className="flex items-center px-3 py-2 bg-slate-50 text-slate-600 rounded text-sm hover:bg-slate-100 border border-slate-200">
                      <Download size={14} className="mr-2" />
                      导出
                  </button>
              </div>

              <div className="relative">
                <input 
                  type="text" 
                  placeholder="搜索意图名称/ID" 
                  className="pl-9 pr-4 py-2 border border-slate-300 rounded text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 w-64"
                />
                <Search className="absolute left-3 top-2.5 text-slate-400" size={16} />
             </div>
              <button 
                onClick={() => { 
                    setFormData({ name: '', category: '', description: '', slotIds: [], utterances: [], recognitionType: 'SEMANTIC', status: 'ACTIVE' }); 
                    setMode('CREATE'); 
                }}
                className="flex items-center px-4 py-2 bg-blue-600 text-white rounded text-sm font-medium hover:bg-blue-700 shadow-sm"
              >
                <Plus size={16} className="mr-2" />
                新建意图
              </button>
           </div>
        </div>

