                                          {type === 'GROUP' ? '按班组' : type === 'AGENT' ? '按座席' : '按业务线'}
                                       </span>
                                    </label>
                                 ))}
                              </div>
                              <select 
                                value={canaryConfig.scopeValue}
                                onChange={(e) => setCanaryConfig({...canaryConfig, scopeValue: e.target.value})}
                                className="w-full md:w-2/3 px-4 py-2 border border-slate-300 rounded bg-white focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                              >
                                {canaryConfig.scopeType === 'GROUP' && (
