                                     <option value="信用卡客服二组">信用卡客服二组 (12人)</option>
                                     <option value="VIP专席">VIP专席 (5人)</option>
                                   </>
                                )}
                                {canaryConfig.scopeType === 'AGENT' && (
                                   <>
                                     <option value="工号 1001">工号 1001 - 张三</option>
                                     <option value="工号 1002">工号 1002 - 李四</option>
                                   </>
                                )}
                                {canaryConfig.scopeType === 'LINE' && (
                                   <>
                                     <option value="信用卡业务">信用卡业务线</option>
                                     <option value="个人贷款">个人贷款业务线</option>
