                               <div className={`text-2xl font-bold ${canaryStats.accuracy > 90 ? 'text-green-600' : 'text-orange-500'}`}>
                                  {canaryStats.accuracy.toFixed(1)}%
                               </div>
                               <div className="text-[10px] text-slate-400 mt-1">基线: 85.0%</div>
                            </div>
                            <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                               <div className="text-xs text-slate-500 font-medium mb-1 flex items-center"><BarChart3 size={14} className="mr-1"/> 实时槽位F1值</div>
                               <div className={`text-2xl font-bold ${canaryStats.slotAccuracy > 85 ? 'text-blue-600' : 'text-orange-500'}`}>
                                  {canaryStats.slotAccuracy.toFixed(1)}%
                               </div>
                               <div className="text-[10px] text-slate-400 mt-1">基线: 80.0%</div>
                            </div>
                            <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                               <div className="text-xs text-slate-500 font-medium mb-1 flex items-center"><Users size={14} className="mr-1"/> 灰度请求量</div>
                               <div className="text-2xl font-bold text-slate-700">
                                  {canaryStats.totalRequests}
                               </div>
                               <div className="text-[10px] text-slate-400 mt-1">异常率: {(canaryStats.errorRate * 100).toFixed(2)}%</div>
                            </div>
                         </div>

                         {/* Realtime Log */}
                         <div className="border border-slate-200 rounded-lg overflow-hidden">
                            <div className="bg-slate-100 px-4 py-2 border-b border-slate-200 text-xs font-semibold text-slate-600 flex justify-between">
                               <span>实时请求日志 (Scope: {canaryConfig.scopeValue})</span>
                               <span className="flex items-center text-green-600"><div className="w-2 h-2 rounded-full bg-green-500 mr-2 animate-pulse"></div>监控中</span>
                            </div>
                            <div className="h-48 bg-slate-900 p-4 font-mono text-xs text-green-400 overflow-y-auto space-y-1">
                                <div className="opacity-50">[SYSTEM] Canary monitoring started at {new Date().toLocaleTimeString()}</div>
                                {Array.from({length: Math.min(8, canaryStats.totalRequests)}).map((_, i) => (
                                   <div key={i} className="flex space-x-2">
                                      <span className="text-slate-500">[{new Date().toLocaleTimeString()}]</span>
                                      <span className="text-blue-400">INFO</span>
                                      <span>Session-{1000+i}: Intent recognized 'Credit_Card_Loss' (Conf: 0.9{8-i})</span>
                                   </div>
                                ))}
                                {canaryStats.totalRequests > 8 && <div className="text-slate-500 italic">... {canaryStats.totalRequests - 8} more events</div>}
                            </div>
                         </div>

                         {/* Threshold Alert */}
                         {canaryStats.accuracy < 85 && (
                             <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded text-sm flex items-center animate-pulse">
                                <AlertTriangle size={18} className="mr-2" />
                                警告：当前意图准确率低于基线值，建议立即终止灰度！
                             </div>
                         )}
                      </div>
                    )}

                  </div>

                  {/* Modal Footer */}
                  <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-between items-center">
                    {canaryStep === 'CONFIG' ? (
                       <>
                         <button onClick={() => setShowCanaryModal(false)} className="px-6 py-2 border border-slate-300 text-slate-700 rounded hover:bg-white transition-colors">取消</button>
                         <button 
                            onClick={handleStartCanary}
                            className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 shadow-md font-medium flex items-center"
                         >
                            <Rocket size={16} className="mr-2" />
                            启动灰度发布
                         </button>
                       </>
                    ) : (
                       <>
                         <button 
                            onClick={() => handleEndCanary('ROLLBACK')}
                            className="px-6 py-2 border border-red-200 text-red-600 bg-red-50 rounded hover:bg-red-100 font-medium flex items-center"
                         >
                            <XCircle size={16} className="mr-2" />
                            终止灰度 (回滚)
                         </button>
                         <div className="text-xs text-slate-400 px-4">灰度倒计时: {canaryConfig.duration}h 00m</div>
                         <button 
                            onClick={() => handleEndCanary('FULL')}
                            className="px-6 py-2 bg-green-600 text-white rounded hover:bg-green-700 shadow-md font-medium flex items-center"
                         >
                            <CheckCircle size={16} className="mr-2" />
                            全量发布
                         </button>
                       </>
                    )}
                  </div>
                </div>
              </div>
            )}

      </div>
      );
  }

  // CREATE / EDIT MODE
  return (
    <div className="bg-white p-8 rounded-lg shadow-sm border border-slate-200 h-full flex flex-col overflow-y-auto custom-scrollbar">
      <div className="flex items-center mb-6 border-b pb-4 flex-shrink-0">
        <button onClick={() => setMode('LIST')} className="mr-4 p-2 hover:bg-slate-100 rounded-full">
          <ChevronLeft size={24} className="text-slate-600" />
        </button>
        <div>
          <h2 className="text-xl font-bold text-slate-800">{mode === 'CREATE' ? '新建意图' : '编辑意图'}</h2>
          <p className="text-sm text-slate-500 mt-1">系统识别到此意图后，将自动尝试提取关联的槽位信息。</p>
        </div>
      </div>

      <div className="space-y-8 max-w-5xl pb-10">
        {/* Basic Info */}
        <div className="grid grid-cols-2 gap-6">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">意图名称 <span className="text-red-500">*</span></label>
            <input 
              type="text" 
              value={formData.name}
              onChange={(e) => setFormData({...formData, name: e.target.value})}
              placeholder="例如：信用卡挂失"
              className="w-full px-4 py-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">意图分类 <span className="text-red-500">*</span></label>
            <select 
              value={formData.category}
              onChange={(e) => setFormData({...formData, category: e.target.value})}
              className="w-full px-4 py-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none bg-white"
            >
              <option value="">请选择分类</option>
              {categories.map(cat => (
                  <React.Fragment key={cat.id}>
                      <option value={cat.name} disabled className="bg-slate-100 font-semibold">{cat.name}</option>
                      {cat.children.map(child => (
                          <option key={child.id} value={`${cat.name}/${child.name}`}>&nbsp;&nbsp;&nbsp;{child.name}</option>
                      ))}
                  </React.Fragment>
              ))}
