                        {formData.recognitionType === 'SEMANTIC' && <div className="w-2 h-2 rounded-full bg-blue-600"></div>}
                    </div>
                    <input 
                        type="radio" 
                        name="recognitionType" 
                        className="hidden" 
                        checked={formData.recognitionType === 'SEMANTIC'}
                        onChange={() => setFormData({...formData, recognitionType: 'SEMANTIC'})}
                    />
                    <div className="flex flex-col">
                        <span className={`text-sm ${formData.recognitionType === 'SEMANTIC' ? 'text-blue-700 font-medium' : 'text-slate-600'}`}>语义识别 (Semantic)</span>
                        <span className="text-xs text-slate-400 mt-0.5">通过深度学习模型泛化识别，无需精确匹配。</span>
                    </div>
                </label>

                <label className="flex items-center cursor-pointer group">
                    <div className={`w-4 h-4 rounded-full border flex items-center justify-center mr-2 transition-colors ${formData.recognitionType === 'RULE' ? 'border-blue-600' : 'border-slate-300 group-hover:border-blue-400'}`}>
                        {formData.recognitionType === 'RULE' && <div className="w-2 h-2 rounded-full bg-blue-600"></div>}
                    </div>
                    <input 
                        type="radio" 
                        name="recognitionType" 
                        className="hidden" 
                        checked={formData.recognitionType === 'RULE'}
                        onChange={() => setFormData({...formData, recognitionType: 'RULE'})}
                    />
                    <div className="flex flex-col">
                        <span className={`text-sm ${formData.recognitionType === 'RULE' ? 'text-blue-700 font-medium' : 'text-slate-600'}`}>关键词/正则识别 (Keyword/Regex)</span>
                        <span className="text-xs text-slate-400 mt-0.5">通过精确的关键词或正则表达式进行强规则匹配。</span>
                    </div>
                </label>
            </div>
          </div>

          <div className="col-span-2">
            <label className="block text-sm font-medium text-slate-700 mb-1">意图描述</label>
            <textarea 
              rows={2}
              value={formData.description}
              onChange={(e) => setFormData({...formData, description: e.target.value})}
              placeholder="描述该意图的业务目标..."
              className="w-full px-4 py-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none resize-none"
            />
          </div>
        </div>

        {/* Slot Association */}
