           <div className="relative max-w-2xl">
              {/* Trigger Input Box */}
              <div 
                  className="w-full border border-slate-300 rounded px-3 py-2 min-h-[42px] flex flex-wrap gap-2 items-center cursor-pointer bg-white hover:border-blue-400 transition-colors focus-within:ring-2 focus-within:ring-blue-500 focus-within:border-transparent"
                  onClick={() => setIsSlotDropdownOpen(!isSlotDropdownOpen)}
              >
                  {(!formData.slotIds || formData.slotIds.length === 0) && (
                      <span className="text-slate-400 text-sm">点击选择需要关联的槽位...</span>
                  )}

                  {formData.slotIds?.map(id => {
                      const slot = slots.find(s => s.id === id);
                      return slot ? (
                          <span key={id} onClick={(e) => { e.stopPropagation(); toggleSlot(id); }} className="bg-blue-50 text-blue-700 px-2 py-0.5 rounded text-sm border border-blue-100 flex items-center hover:bg-blue-100 transition-colors">
                              {slot.name}
                              <X size={14} className="ml-1 text-blue-500 hover:text-blue-800" />
                          </span>
                      ) : null;
                  })}

                  <div className="ml-auto flex items-center pl-2 border-l border-slate-200">
                       <ChevronDown size={16} className={`text-slate-400 transition-transform duration-200 ${isSlotDropdownOpen ? 'rotate-180' : ''}`} />
                  </div>
              </div>

              {/* Dropdown Menu */}
              {isSlotDropdownOpen && (
                  <>
                    <div className="fixed inset-0 z-10" onClick={() => setIsSlotDropdownOpen(false)}></div>
                    <div className="absolute top-full left-0 w-full mt-1 bg-white border border-slate-200 rounded-md shadow-xl z-20 overflow-hidden animate-in fade-in zoom-in-95 duration-100">
                         {/* Search Header */}
                         <div className="p-2 border-b border-slate-100 bg-slate-50">
                             <div className="relative">
                                <Search size={14} className="absolute left-3 top-2.5 text-slate-400" />
                                <input 
                                    type="text"
                                    value={slotSearchQuery}
                                    onChange={(e) => setSlotSearchQuery(e.target.value)}
                                    onClick={(e) => e.stopPropagation()} 
                                    placeholder="搜索槽位名称..."
                                    className="w-full pl-9 pr-3 py-1.5 text-sm border border-slate-200 rounded bg-white focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                                    autoFocus
                                />
                             </div>
                         </div>

                         {/* Slot List */}
                         <div className="max-h-60 overflow-y-auto">
                             {filteredSlots.length > 0 ? (
                                 filteredSlots.map(slot => {
                                    const isSelected = formData.slotIds?.includes(slot.id);
                                    return (
                                     <div 
                                        key={slot.id}
                                        onClick={() => toggleSlot(slot.id)}
                                        className={`px-4 py-3 text-sm cursor-pointer border-b border-slate-50 last:border-0 hover:bg-blue-50/50 flex items-center justify-between transition-colors ${isSelected ? 'bg-blue-50 text-blue-700' : 'text-slate-700'}`}
                                     >
                                        <div className="flex flex-col flex-1 pr-4">
                                            <span className="font-medium">{slot.name}</span>
                                            <span className={`text-xs mt-0.5 truncate ${isSelected ? 'text-blue-500' : 'text-slate-400'}`}>{slot.description || '无描述'}</span>
                                        </div>
                                        {isSelected && <Check size={16} className="text-blue-600 flex-shrink-0" />}
                                     </div>
                                 )})
                             ) : (
                                 <div className="px-4 py-8 text-sm text-slate-400 text-center flex flex-col items-center">
                                    <Search size={24} className="mb-2 text-slate-200" />
                                    未找到匹配的槽位
                                 </div>
                             )}
                         </div>

                         {/* Footer Action */}
                         <div className="p-2 bg-slate-50 border-t border-slate-100 text-xs text-slate-400 text-center">
                            共 {filteredSlots.length} 个结果
                         </div>
                    </div>
                  </>
              )}
           </div>
        </div>

        {/* Utterances */}
        <div className="border-t pt-6">
           <h3 className="text-lg font-semibold text-slate-800 mb-4">
               {formData.recognitionType === 'RULE' ? '规则配置 (关键词/正则)' : '用户相似问'}
           </h3>
           <p className="text-sm text-slate-500 mb-4">
               {formData.recognitionType === 'RULE' 
                   ? '添加精确匹配的关键词或正则表达式。' 
                   : '添加用户表达该意图时可能使用的常见话术，用于训练模型。'}
           </p>

           <div className="flex space-x-2 mb-4">
              <input 
                type="text" 
                value={utteranceInput}
                onChange={(e) => setUtteranceInput(e.target.value)}
                onKeyDown={addUtterance}
                placeholder={formData.recognitionType === 'RULE' ? '输入关键词或正则 (如: ^(挂失|丢失)$) 后按回车' : '输入话术后按回车添加，例如：我的信用卡丢了'}
                className="flex-1 px-4 py-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
              />
              <button 
                onClick={() => {
                   if (utteranceInput.trim()) {
                      setFormData(prev => ({...prev, utterances: [...(prev.utterances || []), utteranceInput.trim()]}));
                      setUtteranceInput('');
                   }
                }}
                className="px-4 py-2 bg-slate-100 text-slate-700 rounded hover:bg-slate-200 font-medium text-sm"
              >
                添加
              </button>
           </div>

           <div className="flex flex-wrap gap-2 bg-slate-50 p-4 rounded min-h-[100px] border border-slate-100 content-start">
              {formData.utterances?.map((u, idx) => (
                 <span key={idx} className="inline-flex items-center px-3 py-1 bg-white border border-slate-200 rounded-full text-sm text-slate-700 shadow-sm">
                    {u}
                    <X 
                      size={14} 
                      className="ml-2 text-slate-400 hover:text-red-500 cursor-pointer" 
                      onClick={() => removeUtterance(idx)}
                    />
                 </span>
              ))}
              {(!formData.utterances || formData.utterances.length === 0) && (
                 <span className="text-slate-400 text-sm italic p-2">
                     {formData.recognitionType === 'RULE' ? '暂无规则配置...' : '暂无示例话术...'}
                 </span>
              )}
           </div>
        </div>

        <div className="border-t pt-6 flex justify-between items-center">
           <div className="flex items-center">
             <label className="mr-3 text-sm font-medium text-slate-700">状态</label>
             <button 
               onClick={() => setFormData(prev => ({ ...prev, status: prev.status === 'ACTIVE' ? 'INACTIVE' : 'ACTIVE' }))}
               className="text-slate-400 hover:text-blue-600 transition-colors"
             >
                {formData.status === 'ACTIVE' ? <ToggleRight size={36} className="text-green-500" /> : <ToggleLeft size={36} />}
             </button>
             <span className={`ml-2 text-sm ${formData.status === 'ACTIVE' ? 'text-green-600' : 'text-slate-400'}`}>
                {formData.status === 'ACTIVE' ? '已启用' : '已停用'}
             </span>
           </div>

           <div className="space-x-4">
              <button 
                onClick={() => setMode('LIST')}
                className="px-6 py-2 border border-slate-300 text-slate-700 rounded hover:bg-slate-50"
              >
                取消
              </button>
              <button 
                onClick={handleSave}
                className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 shadow-sm"
              >
                保存意图配置
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default IntentManager;

