                                 <div className="space-y-3">
                                    {currentKnowledge.logs.length > 0 ? (
                                        currentKnowledge.logs.map((log: any, i: number) => (
                                            <div key={i} className={`p-4 rounded-lg border flex flex-col ${log.bg} ${log.border}`}>
                                                <div className={`flex items-center mb-2 font-bold text-sm ${log.color}`}>
                                                    <log.icon size={16} className="mr-2"/>
                                                    {log.title}
                                                </div>
                                                <div className="text-xs text-slate-600 leading-relaxed pl-6">
                                                    {log.content}
                                                </div>
                                            </div>
                                        ))
                                    ) : (
                                        <div className="p-8 text-center bg-slate-50 rounded border border-slate-100 text-slate-400 text-xs">
                                            暂无系统日志记录
                                        </div>
                                    )}
                                 </div>
                              </div>
                           </div>
                        ) : (
                           <div className="flex-1 flex flex-col items-center justify-center text-slate-400 text-xs">
                              <HelpCircle size={32} className="mb-2 text-slate-200" />
                              <p>请选择左侧知识节点查看详情</p>
                           </div>
                        )}
                    </div>
                 </div>
              </div>

          </div>
       </div>
    </div>
  );
};

