import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import TopNav from './components/TopNav';
import EntityManager from './components/EntityManager';
import SlotManager from './components/SlotManager';
import IntentManager from './components/IntentManager';
import KnowledgeFlow from './components/KnowledgeFlow';
import KnowledgeStats from './components/KnowledgeStats';
import BehaviorAnalysis from './components/BehaviorAnalysis';
import IntentFeedback from './components/IntentFeedback';
import { Entity, Slot, Intent, ViewState } from './types';
import { MOCK_ENTITIES, MOCK_INTENTS, MOCK_SLOTS } from './constants';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>('INTENT');

  // Lifted state to manage dependencies between modules
  const [entities, setEntities] = useState<Entity[]>(MOCK_ENTITIES);
  const [slots, setSlots] = useState<Slot[]>(MOCK_SLOTS);
  const [intents, setIntents] = useState<Intent[]>(MOCK_INTENTS);

  const renderContent = () => {
    switch (currentView) {
      case 'ENTITY':
        return <EntityManager entities={entities} setEntities={setEntities} />;
      case 'SLOT':
        return <SlotManager slots={slots} setSlots={setSlots} entities={entities} />;
      case 'INTENT':
        return <IntentManager intents={intents} setIntents={setIntents} slots={slots} />;
      case 'KNOWLEDGE_FLOW':
        return <KnowledgeFlow />;
      case 'KNOWLEDGE_STATS':
        return <KnowledgeStats />;
      case 'BEHAVIOR_ANALYSIS':
        return <BehaviorAnalysis />;
      case 'INTENT_FEEDBACK':
        return <IntentFeedback />;
      default:
        return <div className="p-10 text-slate-500">Feature coming soon...</div>;
    }
  };

  const getBreadcrumb = () => {
     if (currentView === 'ENTITY' || currentView === 'SLOT' || currentView === 'INTENT') {
         return (
             <>
                <span>智能助手管理</span>
                <span>/</span>
                <span>内容管理</span>
                <span>/</span>
                <span className="text-blue-600 font-medium">
                  {currentView === 'ENTITY' ? '实体管理' : currentView === 'SLOT' ? '槽位管理' : '意图管理'}
                </span>
             </>
         );
     } else if (currentView === 'KNOWLEDGE_FLOW' || currentView === 'KNOWLEDGE_STATS' || currentView === 'BEHAVIOR_ANALYSIS' || currentView === 'INTENT_FEEDBACK') {
         return (
             <>
                <span>统计分析</span>
                <span>/</span>
                <span className="text-blue-600 font-medium">
                  {currentView === 'KNOWLEDGE_FLOW' ? '知识应用流水' : 
                   currentView === 'KNOWLEDGE_STATS' ? '知识应用统计' : 
                   currentView === 'BEHAVIOR_ANALYSIS' ? '助手行为分析' :
                   '意图反馈明细'}
                </span>
             </>
         );
     }
     return <span>智能助手管理</span>;
  };

  return (
    <div className="flex h-screen bg-[#f1f5f9] font-sans text-slate-900 overflow-hidden">
      {/* Left Sidebar */}
      <Sidebar currentView={currentView} onChangeView={setCurrentView} />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0">
        <TopNav />

        {/* Breadcrumb / Page Header Area (Simplified matches screenshot top white bar) */}
        <div className="bg-white border-b border-slate-200 px-6 py-3 text-sm text-slate-500 flex items-center space-x-2">
            {getBreadcrumb()}
        </div>

        {/* Dynamic Content */}
        <div className="flex-1 p-6 overflow-hidden">
          {renderContent()}
        </div>
      </div>
    </div>
  );
}

export default App;

