      const matchAgent = sessionFilters.agentId ? s.agent.includes(sessionFilters.agentId) : true;
      const matchIntent = sessionFilters.intent ? s.intent.includes(sessionFilters.intent) : true;
      const matchStatus = sessionFilters.status === 'ALL' ? true : s.status === sessionFilters.status;
      return matchAgent && matchIntent && matchStatus;
  });
  const totalSessionPages = Math.ceil(filteredSessions.length / ITEMS_PER_PAGE);
  const paginatedSessions = filteredSessions.slice(
    (sessionPage - 1) * ITEMS_PER_PAGE,
    sessionPage * ITEMS_PER_PAGE
  );

  // --- Helper Components ---
  const Pagination = ({ page, total, setPage }: { page: number, total: number, setPage: (p: number) => void }) => (
     <div className="flex items-center justify-between border-t border-slate-100 px-6 py-3">
        <div className="text-xs text-slate-500">
           第 {page} 页 / 共 {total} 页
        </div>
        <div className="flex space-x-1">
           <button 
             onClick={() => setPage(Math.max(1, page - 1))}
             disabled={page === 1}
             className={`p-1 rounded border ${page === 1 ? 'text-slate-300 border-slate-100 cursor-not-allowed' : 'text-slate-600 border-slate-300 hover:bg-slate-50'}`}
           >
              <ChevronLeft size={16} />
           </button>
           {Array.from({ length: total }, (_, i) => i + 1).map(p => (
              <button
                key={p}
                onClick={() => setPage(p)}
                className={`w-6 h-6 flex items-center justify-center rounded text-xs ${p === page ? 'bg-blue-600 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
              >
