              </button>
           ))}
           <button 
             onClick={() => setPage(Math.min(total, page + 1))}
             disabled={page === total}
             className={`p-1 rounded border ${page === total ? 'text-slate-300 border-slate-100 cursor-not-allowed' : 'text-slate-600 border-slate-300 hover:bg-slate-50'}`}
