                          <th className="px-6 py-3 border-b">修正原因 (摘要)</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                      {paginatedList.map(row => (
                          <tr key={row.id} className="hover:bg-slate-50">
                              <td className="px-6 py-4 font-mono text-xs">{row.id}</td>
                              <td className="px-6 py-4 font-mono text-xs">{row.time}</td>
                              <td className="px-6 py-4">{row.agent}</td>
                              <td className="px-6 py-4">
                                  <div className="text-xs text-blue-600 bg-blue-50 p-2 rounded border border-blue-100 leading-relaxed">
