                </button>
            </div>

            {/* Content */}
            <div className="flex-1 overflow-y-auto p-8 prose prose-sm max-w-none text-slate-600">
                {currentKnowledge?.docInfo?.content ? (
                    <div dangerouslySetInnerHTML={{ __html: currentKnowledge.docInfo.content }} />
                ) : (
                    <div className="text-center py-20 text-slate-400">
                        <FileText size={48} className="mx-auto mb-4 text-slate-200"/>
                        <p>暂无文档内容</p>
                    </div>
                )}
            </div>

            {/* Footer / Rating */}
            <div className="p-6 border-t border-slate-100 bg-slate-50">
                <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-1">
                        <span className="text-sm font-bold text-slate-700 mr-2">文档评分:</span>
                        {[1,2,3,4,5].map(i => (
                            <Star 
                                key={i} 
                                size={18} 
                                className={`${i <= (currentKnowledge?.docInfo?.rating || 0) ? 'text-yellow-400 fill-yellow-400' : 'text-slate-200'}`} 
                            />
                        ))}
                    </div>
                    <button onClick={() => setShowDocDrawer(false)} className="px-6 py-2 bg-white border border-slate-300 rounded text-sm hover:bg-slate-50 font-medium text-slate-700 shadow-sm transition-colors">
                        关闭文档
                    </button>
                </div>
            </div>
            </div>
        </div>
        )}

    </div>
  );
};

