    const typeMap: Record<string, string> = {
      'OMISSION': '漏选',
      'OVER': '多选',
      'INCORRECT': '不正确',
      'ADOPTED': '采纳'
    };

    const matchType = filters.correctionTypes.length === 0 || filters.correctionTypes.some(t => item.correctionType === typeMap[t]);

    return matchDate && matchAgent && matchCust && matchTag && matchType;
  });

