             <MetricCard title="不正确率" value={`${metrics.incorrectRate}%`} color="text-red-500" description="推荐标签完全不正确的会话数量/标签推荐会话数" />
         </div>

         {/* Charts */}
         <div className="grid grid-cols-3 gap-6">
             {/* Trend Chart - 2 cols */}
             <div className="col-span-2 border border-slate-200 rounded-lg p-4">
                 <h3 className="text-sm font-bold text-slate-700 mb-4 flex items-center justify-between">
                    <div className="flex items-center"><TrendingUp size={16} className="mr-2 text-blue-500"/> 采纳趋势与正确率</div>
                 </h3>
                 <div className="h-48 w-full relative">
                    <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
                         {/* Grid */}
                         <line x1="0" y1="20" x2="100" y2="20" stroke="#f1f5f9" strokeWidth="0.5" />
                         <line x1="0" y1="50" x2="100" y2="50" stroke="#f1f5f9" strokeWidth="0.5" />
                         <line x1="0" y1="80" x2="100" y2="80" stroke="#f1f5f9" strokeWidth="0.5" />

                         {/* Bars (Count) */}
                         {trendData.count.map((v, i) => {
                             const maxCount = Math.max(...trendData.count) * 1.1;
                             const x = (i / (trendData.count.length - 1)) * 90 + 5; // offset
                             const height = (v / maxCount) * 80; // Scale to fit
                             return (
                                 <g key={`bar-${i}`}>
                                     <rect x={x-2} y={100-height} width="4" height={height} fill="#bfdbfe" opacity="0.8" rx="1" />
                                     {/* Hover tooltip hint could be here */}
                                 </g>
                             );
                         })}

