    overCount: 817,      
    overRate: 6.5,
    incorrectCount: 377, 
    incorrectRate: 3.0
  };

  // Dynamic Trend Data
  const trendData = useMemo(() => {
    let labels: string[] = [];
    let count: number[] = [];
    let accuracy: number[] = [];

    if (timeRange === 'today') {
      labels = ['12/28', '12/29', '12/30', '12/31', '1/1', '1/2', '1/3', '1/4', '1/5'];
