      labels = ['W1', 'W2', 'W3', 'W4'];
      count = [25000, 28000, 26000, 31000];
      accuracy = [78, 79, 77, 80];
    }
    return { labels, count, accuracy };
  }, [timeRange]);

  // Helper for Smooth Path
  const getSmoothPath = (points: {x: number, y: number}[]) => {
    if (points.length < 2) return "";
    let d = `M ${points[0].x} ${points[0].y}`;
    for (let i = 1; i < points.length; i++) {
      const cp1x = points[i - 1].x + (points[i].x - points[i - 1].x) / 2;
      const cp1y = points[i - 1].y;
      const cp2x = points[i - 1].x + (points[i].x - points[i - 1].x) / 2;
      const cp2y = points[i].y;
      d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${points[i].x} ${points[i].y}`;
    }
    return d;
  };

  // Mock List Data
  const sessionList = Array.from({ length: 25 }, (_, i) => {
