    const typeLabel = type === 'ADOPTED' ? '采纳' : type === 'OMISSION' ? '漏选' : type === 'OVER' ? '多选' : '不正确';

    return {
      id: `HH${1001 + i}`,
      time: `2023-11-05 10:${(10 + i).toString().padStart(2, '0')}`,
      agent: `1002${i % 5}`,
      cust: `cust_${8800 + i}`,
      recSummary: i % 2 === 0 ? '信用卡-查询-查询余额' : '信用卡-操作-转账失败, 手机银行-问题-网络问题',
      finalSummary: type === 'ADOPTED' 
        ? (i % 2 === 0 ? '信用卡-查询-查询余额' : '信用卡-操作-转账失败, 手机银行-问题-网络问题') 
        : (type === 'OMISSION' ? '信用卡-查询-查询余额, 信用卡-账单-费用疑问' : '信用卡-操作-转账到账时间'),
      correctionType: typeLabel,
      reason: type === 'ADOPTED' ? '—' : type === 'OMISSION' ? '“客户主要问手续费”' : type === 'OVER' ? '“其实是正常延迟”' : '“意图识别错误”'
    };
  });

  // Filter Logic
  const handleCorrectionTypeChange = (type: string) => {
    setFilters(prev => {
      if (prev.correctionTypes.includes(type)) {
        return { ...prev, correctionTypes: prev.correctionTypes.filter(t => t !== type) };
      } else {
        return { ...prev, correctionTypes: [...prev.correctionTypes, type] };
      }
    });
    setPage(1);
