                onClick={() => setPage(p)}
                className={`w-6 h-6 flex items-center justify-center rounded text-xs ${p === page ? 'bg-blue-600 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
              >
                 {p}
              </button>
           ))}
           <button 
             onClick={() => setPage(Math.min(totalPages, page + 1))}
             disabled={page === totalPages}
             className={`p-1 rounded border ${page === totalPages ? 'text-slate-300 border-slate-100 cursor-not-allowed' : 'text-slate-600 border-slate-300 hover:bg-slate-50'}`}
           >
              <ChevronRight size={16} />
           </button>
        </div>
     </div>
  );

  const renderTags = (text: string) => {
      if (!text || text === '—') return text;
