      const accPoints = trendData.accuracy.map((v, i) => ({
          x: (i / (trendData.accuracy.length - 1)) * 90 + 5,
          y: 100 - (v / maxAcc) * 80
      }));

      return { maxCount, accPoints };
  };
  const { maxCount, accPoints } = getChartPoints();

