             <MetricCard title="多选率" value={`${metrics.overRate}%`} color="text-yellow-500" description="推荐标签有多选的会话数量/标签推荐会话数" />
             <MetricCard title="不正确率" value={`${metrics.incorrectRate}%`} color="text-red-500" description="推荐标签完全不正确的会话数量/标签推荐会话数" />
         </div>

