                              <td className="px-6 py-4">{row.agent}</td>
                              <td className="px-6 py-4">
                                  {renderTags(row.recSummary)}
                              </td>
                              <td className="px-6 py-4">
                                  {renderTags(row.finalSummary)}
                              </td>
                              <td className="px-6 py-4 text-center">
                                  <span className={`px-2 py-1 rounded text-xs border ${
                                      row.correctionType === '漏选' ? 'bg-orange-50 text-orange-600 border-orange-200' :
                                      row.correctionType === '多选' ? 'bg-yellow-50 text-yellow-600 border-yellow-200' :
                                      row.correctionType === '不正确' ? 'bg-red-50 text-red-600 border-red-200' :
                                      'bg-green-50 text-green-600 border-green-200'
                                  }`}>
                                      {row.correctionType}
                                  </span>
                              </td>
                              <td className="px-6 py-4 text-xs text-slate-500 italic">
                                  {row.reason}
                              </td>
                          </tr>
                      ))}
                      {paginatedList.length === 0 && (
                          <tr><td colSpan={7} className="text-center py-8 text-slate-400">无匹配数据</td></tr>
                      )}
                  </tbody>
              </table>
              <Pagination />
          </div>
      </section>
    </div>
  );
};

