import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart2, Filter, Search, Calendar, ChevronLeft, ChevronRight,
  AlertCircle, CheckCircle, XCircle, TrendingUp,
  FileText, ClipboardList, AlertTriangle, ChevronDown, X, HelpCircle
} from 'lucide-react';

const SummaryFeedback: React.FC = () => {
  const [timeRange, setTimeRange] = useState('today');
  const [page, setPage] = useState(1);
  const ITEMS_PER_PAGE = 10;

  // Chart Interaction
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const chartRef = useRef<HTMLDivElement>(null);

  // Filters
  const [filters, setFilters] = useState({
    date: '',
    agentId: '',
    custId: '',
    tag: '',
    correctionTypes: [] as string[]
  });

  const [isTypeDropdownOpen, setIsTypeDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsTypeDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Mock Data
  const metrics = {
    totalSessions: 12580,
    recSessions: 9850,
    adoptedSessions: 7683,
    accuracy: 78.0,
    omissionCount: 1572, 
    omissionRate: 12.5,
    overCount: 817,      
    overRate: 6.5,
    incorrectCount: 377, 
    incorrectRate: 3.0
  };

  // Dynamic Trend Data
  const trendData = useMemo(() => {
    let labels: string[] = [];
    let count: number[] = [];
    let accuracy: number[] = [];

    if (timeRange === 'today') {
      labels = ['12/28', '12/29', '12/30', '12/31', '1/1', '1/2', '1/3', '1/4', '1/5'];
      count = [450, 890, 1100, 950, 1020, 800, 560, 900, 950];
      accuracy = [75, 78, 80, 79, 77, 81, 82, 80, 79];
    } else if (timeRange === '7days') {
      labels = ['11-01', '11-02', '11-03', '11-04', '11-05', '11-06', '11-07'];
      count = [5200, 6100, 5800, 4900, 5100, 6300, 6500];
      accuracy = [76, 77, 79, 78, 80, 81, 79];
    } else {
      labels = ['W1', 'W2', 'W3', 'W4'];
      count = [25000, 28000, 26000, 31000];
      accuracy = [78, 79, 77, 80];
    }
    return { labels, count, accuracy };
  }, [timeRange]);

  // Helper for Smooth Path
  const getSmoothPath = (points: {x: number, y: number}[]) => {
    if (points.length < 2) return "";
    let d = `M ${points[0].x} ${points[0].y}`;
    for (let i = 1; i < points.length; i++) {
      const cp1x = points[i - 1].x + (points[i].x - points[i - 1].x) / 2;
      const cp1y = points[i - 1].y;
      const cp2x = points[i - 1].x + (points[i].x - points[i - 1].x) / 2;
      const cp2y = points[i].y;
      d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${points[i].x} ${points[i].y}`;
    }
    return d;
  };

  // Mock List Data
  const sessionList = Array.from({ length: 25 }, (_, i) => {
    const type = i % 10 < 6 ? 'ADOPTED' : i % 10 < 8 ? 'OMISSION' : i % 10 < 9 ? 'OVER' : 'INCORRECT';
    const typeLabel = type === 'ADOPTED' ? '采纳' : type === 'OMISSION' ? '漏选' : type === 'OVER' ? '多选' : '不正确';

    return {
      id: `HH${1001 + i}`,
      time: `2023-11-05 10:${(10 + i).toString().padStart(2, '0')}`,
      agent: `1002${i % 5}`,
      cust: `cust_${8800 + i}`,
      recSummary: i % 2 === 0 ? '信用卡-查询-查询余额' : '信用卡-操作-转账失败, 手机银行-问题-网络问题',
      finalSummary: type === 'ADOPTED' 
        ? (i % 2 === 0 ? '信用卡-查询-查询余额' : '信用卡-操作-转账失败, 手机银行-问题-网络问题') 
        : (type === 'OMISSION' ? '信用卡-查询-查询余额, 信用卡-账单-费用疑问' : '信用卡-操作-转账到账时间'),
      correctionType: typeLabel,
      reason: type === 'ADOPTED' ? '—' : type === 'OMISSION' ? '“客户主要问手续费”' : type === 'OVER' ? '“其实是正常延迟”' : '“意图识别错误”'
    };
  });

  // Filter Logic
  const handleCorrectionTypeChange = (type: string) => {
    setFilters(prev => {
      if (prev.correctionTypes.includes(type)) {
        return { ...prev, correctionTypes: prev.correctionTypes.filter(t => t !== type) };
      } else {
        return { ...prev, correctionTypes: [...prev.correctionTypes, type] };
      }
    });
    setPage(1);
  };

  const handleTimeRangeChange = (val: string) => {
      setTimeRange(val);
      setHoverIndex(null);
  }

  const handleChartMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      if (!chartRef.current) return;
      const rect = chartRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const width = rect.width;

      const count = trendData.labels.length;
      if (count < 2) return;

      const sectionWidth = width / (count - 1);
      const index = Math.round(x / sectionWidth);

      if (index >= 0 && index < count) {
          setHoverIndex(index);
      }
  };

  const handleChartMouseLeave = () => {
      setHoverIndex(null);
  };

  const filteredList = sessionList.filter(item => {
    const matchDate = !filters.date || item.time.startsWith(filters.date);
    const matchAgent = !filters.agentId || item.agent.includes(filters.agentId);
    const matchCust = !filters.custId || item.cust.includes(filters.custId);
    const matchTag = !filters.tag || item.recSummary.includes(filters.tag) || item.finalSummary.includes(filters.tag);

    const typeMap: Record<string, string> = {
      'OMISSION': '漏选',
      'OVER': '多选',
      'INCORRECT': '不正确',
      'ADOPTED': '采纳'
    };

    const matchType = filters.correctionTypes.length === 0 || filters.correctionTypes.some(t => item.correctionType === typeMap[t]);

    return matchDate && matchAgent && matchCust && matchTag && matchType;
  });

  const totalPages = Math.ceil(filteredList.length / ITEMS_PER_PAGE);
  const paginatedList = filteredList.slice((page - 1) * ITEMS_PER_PAGE, page * ITEMS_PER_PAGE);

  // Helper Components
  const MetricCard = ({ title, value, color, description }: any) => (
    <div className="p-4 bg-white rounded-lg border border-slate-200 shadow-sm flex flex-col justify-between">
       <div className="text-xs text-slate-500 font-medium uppercase mb-2 flex items-center">
          {title}
          {description && (
              <div className="relative group ml-1 cursor-help">
                  <HelpCircle size={12} className="text-slate-400"/>
                  <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-56 p-2 bg-slate-800 text-white text-xs rounded shadow-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-50 pointer-events-none leading-relaxed text-left">
                      {description}
                      <div className="absolute left-1/2 -translate-x-1/2 -bottom-1 w-2 h-2 bg-slate-800 rotate-45"></div>
                  </div>
              </div>
          )}
       </div>
       <div className={`text-2xl font-bold ${color || 'text-slate-800'}`}>{value}</div>
    </div>
  );

  const Pagination = () => (
     <div className="flex items-center justify-between border-t border-slate-100 px-6 py-3 bg-white rounded-b-lg">
        <div className="text-xs text-slate-500">
           第 {page} 页 / 共 {totalPages} 页
        </div>
        <div className="flex space-x-1">
           <button 
             onClick={() => setPage(Math.max(1, page - 1))}
             disabled={page === 1}
             className={`p-1 rounded border ${page === 1 ? 'text-slate-300 border-slate-100 cursor-not-allowed' : 'text-slate-600 border-slate-300 hover:bg-slate-50'}`}
           >
              <ChevronLeft size={16} />
           </button>
           {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
              <button
                key={p}
                onClick={() => setPage(p)}
                className={`w-6 h-6 flex items-center justify-center rounded text-xs ${p === page ? 'bg-blue-600 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
              >
                 {p}
              </button>
           ))}
           <button 
             onClick={() => setPage(Math.min(totalPages, page + 1))}
             disabled={page === totalPages}
             className={`p-1 rounded border ${page === totalPages ? 'text-slate-300 border-slate-100 cursor-not-allowed' : 'text-slate-600 border-slate-300 hover:bg-slate-50'}`}
           >
              <ChevronRight size={16} />
           </button>
        </div>
     </div>
  );

  const renderTags = (text: string) => {
      if (!text || text === '—') return text;
      // Split by comma or Chinese comma
      const tags = text.split(/,|，/);
      return (
          <div className="flex flex-wrap gap-1">
              {tags.map((t, idx) => (
                  <span key={idx} className="inline-block px-1.5 py-0.5 rounded border border-slate-200 bg-slate-50 text-slate-600 text-[10px]">
                      {t.trim()}
                  </span>
              ))}
          </div>
      );
  };

  // Calc Points for charts
  const getChartPoints = () => {
      const maxCount = Math.max(...trendData.count) * 1.2;
      const maxAcc = 100;

      const accPoints = trendData.accuracy.map((v, i) => ({
          x: (i / (trendData.accuracy.length - 1)) * 90 + 5,
          y: 100 - (v / maxAcc) * 80
      }));

      return { maxCount, accPoints };
  };
  const { maxCount, accPoints } = getChartPoints();

  return (
    <div className="h-full overflow-y-auto custom-scrollbar space-y-6">

      {/* --- DASHBOARD --- */}
      <section className="bg-white p-6 rounded-lg border border-slate-200 shadow-sm">
        <div className="flex justify-between items-center mb-6">
            <h2 className="text-lg font-bold text-slate-800 flex items-center">
               <ClipboardList size={20} className="mr-2 text-blue-600" />
               反馈总览看板
            </h2>

            <div className="flex bg-slate-100 p-1 rounded-lg">
               {['today', '7days', '30days', 'custom'].map(t => (
                  <button 
                    key={t}
                    onClick={() => handleTimeRangeChange(t)}
                    className={`px-3 py-1.5 text-xs font-medium rounded transition-all ${timeRange === t ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                     {t === 'today' ? '今日' : t === '7days' ? '近7天' : t === '30days' ? '近30天' : '自定义'}
                  </button>
               ))}
            </div>
         </div>

         {/* Metrics Grid - Top Row */}
         <div className="grid grid-cols-3 gap-6 mb-6">
             <MetricCard title="会话总数" value={metrics.totalSessions.toLocaleString()} description="所有会话数量" />
             <MetricCard title="标签推荐会话数" value={metrics.recSessions.toLocaleString()} description="在所有的会话中，使用了标签推荐功能的会话数量" />
             <MetricCard title="标签采纳会话数" value={metrics.adoptedSessions.toLocaleString()} color="text-green-600" description="推荐的会话标签完全被坐席采用的会话数量" />
         </div>
         {/* Metrics Grid - Bottom Row */}
         <div className="grid grid-cols-4 gap-6 mb-8">
             <MetricCard title="正确率" value={`${metrics.accuracy}%`} color="text-green-600" description="标签采纳会话数/标签推荐会话数" />
             <MetricCard title="漏选率" value={`${metrics.omissionRate}%`} color="text-orange-500" description="推荐标签有遗漏的会话数量/标签推荐会话数" />
             <MetricCard title="多选率" value={`${metrics.overRate}%`} color="text-yellow-500" description="推荐标签有多选的会话数量/标签推荐会话数" />
             <MetricCard title="不正确率" value={`${metrics.incorrectRate}%`} color="text-red-500" description="推荐标签完全不正确的会话数量/标签推荐会话数" />
         </div>

         {/* Charts */}
         <div className="grid grid-cols-3 gap-6">
             {/* Trend Chart - 2 cols */}
             <div className="col-span-2 border border-slate-200 rounded-lg p-4 bg-white">
                 <h3 className="text-sm font-bold text-slate-700 mb-4 flex items-center justify-between border-l-4 border-blue-500 pl-2">
                    采纳趋势与正确率
                 </h3>
                 <div 
                    ref={chartRef}
                    className="h-48 w-full relative pl-2 cursor-crosshair group"
                    onMouseMove={handleChartMouseMove}
                    onMouseLeave={handleChartMouseLeave}
                 >
                    {/* Tooltip */}
                    {hoverIndex !== null && (
                      <div 
                        className="absolute z-20 bg-slate-800 text-white text-xs rounded p-2 shadow-lg pointer-events-none transition-all duration-75"
                        style={{ 
                            left: `${(hoverIndex / (trendData.labels.length - 1)) * 90 + 5}%`, 
                            top: '0',
                            transform: 'translate(-50%, -110%)'
                        }}
                      >
                          <div className="font-bold mb-1 border-b border-slate-600 pb-1">{trendData.labels[hoverIndex]}</div>
                          <div className="flex items-center justify-between space-x-3">
                              <span className="flex items-center"><div className="w-2 h-2 rounded-full bg-blue-500 mr-1"></div>采纳数:</span>
                              <span className="font-mono">{trendData.count[hoverIndex]}</span>
                          </div>
                          <div className="flex items-center justify-between space-x-3">
                              <span className="flex items-center"><div className="w-2 h-2 rounded-full bg-purple-500 mr-1"></div>正确率:</span>
                              <span className="font-mono">{trendData.accuracy[hoverIndex]}%</span>
                          </div>
                      </div>
                    )}

                    <svg className="w-full h-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
                         {/* Grid */}
                         <line x1="0" y1="20" x2="100" y2="20" stroke="#f1f5f9" strokeWidth="0.5" strokeDasharray="2" />
                         <line x1="0" y1="50" x2="100" y2="50" stroke="#f1f5f9" strokeWidth="0.5" strokeDasharray="2" />
                         <line x1="0" y1="80" x2="100" y2="80" stroke="#f1f5f9" strokeWidth="0.5" strokeDasharray="2" />
                         <line x1="0" y1="100" x2="100" y2="100" stroke="#f1f5f9" strokeWidth="0.5" />

                         {/* Vertical Hover Line */}
                         {hoverIndex !== null && (
                             <line 
                                x1={(hoverIndex / (trendData.labels.length - 1)) * 90 + 5} 
                                y1="0" 
                                x2={(hoverIndex / (trendData.labels.length - 1)) * 90 + 5} 
                                y2="100" 
                                stroke="#94a3b8" 
                                strokeWidth="1" 
                                strokeDasharray="4"
                             />
                         )}

                         {/* Bars (Count) - Blue #3b82f6 */}
                         {trendData.count.map((v, i) => {
                             const x = (i / (trendData.count.length - 1)) * 90 + 5; 
                             const height = (v / maxCount) * 80; 
                             return (
                                 <g key={`bar-${i}`}>
                                     <rect 
                                        x={x-2} 
                                        y={100-height} 
                                        width="4" 
                                        height={height} 
                                        fill={hoverIndex === i ? "#2563eb" : "#3b82f6"} 
                                        rx="1" 
                                        opacity={hoverIndex === null || hoverIndex === i ? 1 : 0.6}
                                     />
                                 </g>
                             );
                         })}

                         {/* Line (Accuracy) - Purple #a855f7 - Smooth & Thin */}
                         <path 
                            d={getSmoothPath(accPoints)}
                            fill="none" 
                            stroke="#a855f7" 
                            strokeWidth="1.5" 
                         />

                         {/* Active Dot for Line */}
                         {hoverIndex !== null && (
                            <circle 
                                cx={accPoints[hoverIndex].x} 
                                cy={accPoints[hoverIndex].y} 
                                r="3" 
                                fill="white" 
                                stroke="#a855f7" 
                                strokeWidth="2" 
                            />
                         )}
                    </svg>
                    {/* X Axis */}
                    <div className="absolute bottom-0 w-full flex justify-between px-2 text-[10px] text-slate-400 translate-y-5">
                        {trendData.labels.map((l,i) => <span key={i}>{l}</span>)}
                    </div>
                 </div>
                 {/* Legend */}
                 <div className="flex justify-center mt-8 space-x-6 text-[10px]">
                   <div className="flex items-center text-slate-600">
                       <div className="w-2 h-2 rounded bg-blue-500 mr-1.5"></div>
                       采纳数 (左轴)
                   </div>
                   <div className="flex items-center text-slate-600">
                       <div className="w-2 h-2 rounded-full border-2 border-purple-500 bg-white mr-1.5 flex items-center justify-center">
                           <div className="w-1.5 h-0.5 bg-purple-500 absolute ml-3"></div>
                           <div className="w-1.5 h-0.5 bg-purple-500 absolute -ml-3"></div>
                       </div>
                       正确率 (右轴)
                   </div>
               </div>
             </div>

             {/* Distribution Chart - 1 col - Updated to Counts */}
             <div className="col-span-1 border border-slate-200 rounded-lg p-4">
                 <h3 className="text-sm font-bold text-slate-700 mb-4 flex items-center border-l-4 border-red-500 pl-2">
                    不准确类型分布 (数量)
                 </h3>
                 <div className="h-48 flex items-end justify-around pb-4 px-4 space-x-6 pt-6">
                     {/* Omission - Orange */}
                     <div className="flex flex-col items-center flex-1 h-full justify-end group relative">
                         <div className="text-xs font-bold text-slate-600 mb-2">{metrics.omissionCount}</div>
                         <div className="w-4 bg-orange-500 rounded-t relative hover:opacity-80 transition-opacity" style={{height: `${(metrics.omissionCount / 2000) * 80}%`}}></div>
                         <div className="text-[10px] text-slate-500 mt-2">漏选</div>
                     </div>
                     {/* Over - Yellow */}
                     <div className="flex flex-col items-center flex-1 h-full justify-end group relative">
                         <div className="text-xs font-bold text-slate-600 mb-2">{metrics.overCount}</div>
                         <div className="w-4 bg-yellow-500 rounded-t relative hover:opacity-80 transition-opacity" style={{height: `${(metrics.overCount / 2000) * 80}%`}}></div>
                         <div className="text-[10px] text-slate-500 mt-2">多选</div>
                     </div>
                     {/* Incorrect - Red */}
                     <div className="flex flex-col items-center flex-1 h-full justify-end group relative">
                         <div className="text-xs font-bold text-slate-600 mb-2">{metrics.incorrectCount}</div>
                         <div className="w-4 bg-red-500 rounded-t relative hover:opacity-80 transition-opacity" style={{height: `${(metrics.incorrectCount / 2000) * 80}%`}}></div>
                         <div className="text-[10px] text-slate-500 mt-2">不正确</div>
                     </div>
                 </div>
                 {/* Simple Legend */}
                 <div className="flex justify-center mt-2 space-x-3 text-[10px]">
                     <div className="flex items-center"><div className="w-1.5 h-1.5 bg-orange-500 mr-1 rounded-sm"></div>漏选</div>
                     <div className="flex items-center"><div className="w-1.5 h-1.5 bg-yellow-500 mr-1 rounded-sm"></div>多选</div>
                     <div className="flex items-center"><div className="w-1.5 h-1.5 bg-red-500 mr-1 rounded-sm"></div>不正确</div>
                 </div>
             </div>
         </div>
      </section>

      {/* --- DETAIL LIST --- */}
      <section className="bg-white rounded-lg border border-slate-200 shadow-sm flex flex-col">
          <div className="p-6 pb-0">
             <h2 className="text-lg font-bold text-slate-800 mb-4">会话明细列表</h2>

             {/* Filters */}
             <div className="bg-slate-50 p-4 rounded-lg border border-slate-100 grid grid-cols-5 gap-4 mb-6">
                 <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">日期</label>
                    <input 
                       type="date" 
                       value={filters.date}
                       onChange={(e) => { setFilters({...filters, date: e.target.value}); setPage(1); }}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">客服工号</label>
                    <input 
                       type="text" 
                       placeholder="输入工号"
                       value={filters.agentId}
                       onChange={(e) => { setFilters({...filters, agentId: e.target.value}); setPage(1); }}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">客户ID</label>
                    <input 
                       type="text" 
                       placeholder="输入客户ID"
                       value={filters.custId}
                       onChange={(e) => { setFilters({...filters, custId: e.target.value}); setPage(1); }}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">小结标签</label>
                    <input 
                       type="text" 
                       placeholder="搜索标签..."
                       value={filters.tag}
                       onChange={(e) => { setFilters({...filters, tag: e.target.value}); setPage(1); }}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                 </div>
                 <div className="relative" ref={dropdownRef}>
                    <label className="block text-xs font-medium text-slate-500 mb-1">修正类型 (多选)</label>
                    <button 
                       onClick={() => setIsTypeDropdownOpen(!isTypeDropdownOpen)}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white flex justify-between items-center focus:outline-none focus:ring-1 focus:ring-blue-500"
                    >
                       <span className={`truncate ${filters.correctionTypes.length ? 'text-slate-800' : 'text-slate-400'}`}>
                          {filters.correctionTypes.length > 0 ? filters.correctionTypes.map(t => t === 'OMISSION' ? '漏选' : t === 'OVER' ? '多选' : t === 'INCORRECT' ? '不正确' : '采纳').join(', ') : '选择类型'}
                       </span>
                       <ChevronDown size={14} className="text-slate-400 flex-shrink-0" />
                    </button>

                    {isTypeDropdownOpen && (
                        <div className="absolute top-full left-0 w-full mt-1 bg-white border border-slate-200 rounded shadow-lg z-10 p-2 space-y-1">
                           {['ADOPTED', 'OMISSION', 'OVER', 'INCORRECT'].map(type => {
                               const label = type === 'ADOPTED' ? '采纳' : type === 'OMISSION' ? '漏选' : type === 'OVER' ? '多选' : '不正确';
                               const isSelected = filters.correctionTypes.includes(type);
                               return (
                                   <div 
                                      key={type} 
                                      onClick={() => handleCorrectionTypeChange(type)}
                                      className="flex items-center px-2 py-1.5 hover:bg-slate-50 rounded cursor-pointer text-sm"
                                   >
                                      <div className={`w-3 h-3 border rounded mr-2 flex items-center justify-center ${isSelected ? 'bg-blue-600 border-blue-600' : 'border-slate-300'}`}>
                                          {isSelected && <div className="w-1.5 h-1.5 bg-white rounded-sm"></div>}
                                      </div>
                                      <span className="text-slate-700">{label}</span>
                                   </div>
                               );
                           })}
                        </div>
                    )}
                 </div>
             </div>
          </div>

          <div className="border-t border-slate-100">
              <table className="w-full text-sm text-left text-slate-600">
                  <thead className="bg-slate-50 text-slate-700 font-semibold">
                      <tr>
                          <th className="px-6 py-3 border-b whitespace-nowrap">会话ID</th>
                          <th className="px-6 py-3 border-b whitespace-nowrap">时间</th>
                          <th className="px-6 py-3 border-b whitespace-nowrap">客服工号</th>
                          <th className="px-6 py-3 border-b w-1/4">推荐标签</th>
                          <th className="px-6 py-3 border-b w-1/4">最终标签</th>
                          <th className="px-6 py-3 border-b whitespace-nowrap text-center">修正类型</th>
                          <th className="px-6 py-3 border-b">修正原因</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                      {paginatedList.map(row => (
                          <tr key={row.id} className="hover:bg-slate-50">
                              <td className="px-6 py-4 font-mono text-xs">{row.id}</td>
                              <td className="px-6 py-4 font-mono text-xs">{row.time}</td>
                              <td className="px-6 py-4">{row.agent}</td>
                              <td className="px-6 py-4">
                                  {renderTags(row.recSummary)}
                              </td>
                              <td className="px-6 py-4">
                                  {renderTags(row.finalSummary)}
                              </td>
                              <td className="px-6 py-4 text-center">
                                  <span className={`px-2 py-1 rounded text-xs border ${
                                      row.correctionType === '漏选' ? 'bg-orange-50 text-orange-600 border-orange-200' :
                                      row.correctionType === '多选' ? 'bg-yellow-50 text-yellow-600 border-yellow-200' :
                                      row.correctionType === '不正确' ? 'bg-red-50 text-red-600 border-red-200' :
                                      'bg-green-50 text-green-600 border-green-200'
                                  }`}>
                                      {row.correctionType}
                                  </span>
                              </td>
                              <td className="px-6 py-4 text-xs text-slate-500 italic">
                                  {row.reason}
                              </td>
                          </tr>
                      ))}
                      {paginatedList.length === 0 && (
                          <tr><td colSpan={7} className="text-center py-8 text-slate-400">无匹配数据</td></tr>
                      )}
                  </tbody>
              </table>
              <Pagination />
          </div>
      </section>
    </div>
  );
};

