import React, { useState, useMemo, useRef } from 'react';
import { 
  ThumbsUp, ThumbsDown, Filter, Calendar, 
  Search, Eye, Clock, BarChart2, TrendingUp, 
  MessageSquare, User, AlertCircle, X, ChevronDown, 
  CheckCircle, XCircle, ArrowUpRight, ArrowDownRight, Bot,
  ChevronLeft, ChevronRight, HelpCircle
} from 'lucide-react';

const IntentFeedback: React.FC = () => {
