      accuracy = [72, 70, 68, 74, 76, 78, 80, 79, 77, 81, 82, 75];
    } else if (timeRange === '7days') {
      labels = ['11-01', '11-02', '11-03', '11-04', '11-05', '11-06', '11-07'];
