      const rect = chartRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const width = rect.width;

      const count = trendData.labels.length;
      if (count < 2) return;

      const sectionWidth = width / (count - 1);
      const index = Math.round(x / sectionWidth);

      if (index >= 0 && index < count) {
          setHoverIndex(index);
      }
  };

  const handleChartMouseLeave = () => {
      setHoverIndex(null);
  };

  const filteredList = sessionList.filter(item => {
    const matchDate = !filters.date || item.time.startsWith(filters.date);
    const matchAgent = !filters.agentId || item.agent.includes(filters.agentId);
    const matchCust = !filters.custId || item.cust.includes(filters.custId);
    const matchTag = !filters.tag || item.recSummary.includes(filters.tag) || item.finalSummary.includes(filters.tag);

    const typeMap: Record<string, string> = {
      'OMISSION': '漏选',
      'OVER': '多选',
      'INCORRECT': '不正确',
      'ADOPTED': '采纳'
    };

    const matchType = filters.correctionTypes.length === 0 || filters.correctionTypes.some(t => item.correctionType === typeMap[t]);

    return matchDate && matchAgent && matchCust && matchTag && matchType;
  });

