                        }}
                      >
                          <div className="font-bold mb-1 border-b border-slate-600 pb-1">{trendData.labels[hoverIndex]}</div>
                          <div className="flex items-center justify-between space-x-3">
                              <span className="flex items-center"><div className="w-2 h-2 rounded-full bg-blue-500 mr-1"></div>采纳数:</span>
                              <span className="font-mono">{trendData.count[hoverIndex]}</span>
                          </div>
                          <div className="flex items-center justify-between space-x-3">
                              <span className="flex items-center"><div className="w-2 h-2 rounded-full bg-purple-500 mr-1"></div>正确率:</span>
                              <span className="font-mono">{trendData.accuracy[hoverIndex]}%</span>
                          </div>
                      </div>
                    )}

                    <svg className="w-full h-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
                         {/* Grid */}
                         <line x1="0" y1="20" x2="100" y2="20" stroke="#f1f5f9" strokeWidth="0.5" strokeDasharray="2" />
                         <line x1="0" y1="50" x2="100" y2="50" stroke="#f1f5f9" strokeWidth="0.5" strokeDasharray="2" />
                         <line x1="0" y1="80" x2="100" y2="80" stroke="#f1f5f9" strokeWidth="0.5" strokeDasharray="2" />
                         <line x1="0" y1="100" x2="100" y2="100" stroke="#f1f5f9" strokeWidth="0.5" />

                         {/* Vertical Hover Line */}
                         {hoverIndex !== null && (
                             <line 
                                x1={(hoverIndex / (trendData.labels.length - 1)) * 90 + 5} 
                                y1="0" 
                                x2={(hoverIndex / (trendData.labels.length - 1)) * 90 + 5} 
                                y2="100" 
                                stroke="#94a3b8" 
                                strokeWidth="1" 
                                strokeDasharray="4"
                             />
                         )}

                         {/* Bars (Count) - Blue #3b82f6 */}
                         {trendData.count.map((v, i) => {
                             const x = (i / (trendData.count.length - 1)) * 90 + 5; 
                             const height = (v / maxCount) * 80; 
                             return (
                                 <g key={`bar-${i}`}>
                                     <rect 
                                        x={x-2} 
                                        y={100-height} 
                                        width="4" 
                                        height={height} 
                                        fill={hoverIndex === i ? "#2563eb" : "#3b82f6"} 
                                        rx="1" 
                                        opacity={hoverIndex === null || hoverIndex === i ? 1 : 0.6}
                                     />
                                 </g>
                             );
                         })}

                         {/* Line (Accuracy) - Purple #a855f7 - Smooth & Thin */}
                         <path 
                            d={getSmoothPath(accPoints)}
                            fill="none" 
                            stroke="#a855f7" 
                            strokeWidth="1.5" 
                         />

                         {/* Active Dot for Line */}
                         {hoverIndex !== null && (
                            <circle 
                                cx={accPoints[hoverIndex].x} 
                                cy={accPoints[hoverIndex].y} 
                                r="3" 
                                fill="white" 
                                stroke="#a855f7" 
                                strokeWidth="2" 
                            />
                         )}
                    </svg>
                    {/* X Axis */}
                    <div className="absolute bottom-0 w-full flex justify-between px-2 text-[10px] text-slate-400 translate-y-5">
                        {trendData.labels.map((l,i) => <span key={i}>{l}</span>)}
                    </div>
                 </div>
                 {/* Legend */}
                 <div className="flex justify-center mt-8 space-x-6 text-[10px]">
                   <div className="flex items-center text-slate-600">
                       <div className="w-2 h-2 rounded bg-blue-500 mr-1.5"></div>
                       采纳数 (左轴)
                   </div>
                   <div className="flex items-center text-slate-600">
                       <div className="w-2 h-2 rounded-full border-2 border-purple-500 bg-white mr-1.5 flex items-center justify-center">
                           <div className="w-1.5 h-0.5 bg-purple-500 absolute ml-3"></div>
                           <div className="w-1.5 h-0.5 bg-purple-500 absolute -ml-3"></div>
                       </div>
                       正确率 (右轴)
                   </div>
               </div>
             </div>

             {/* Distribution Chart - 1 col - Updated to Counts */}
             <div className="col-span-1 border border-slate-200 rounded-lg p-4">
                 <h3 className="text-sm font-bold text-slate-700 mb-4 flex items-center border-l-4 border-red-500 pl-2">
                    不准确类型分布 (数量)
                 </h3>
                 <div className="h-48 flex items-end justify-around pb-4 px-4 space-x-6 pt-6">
                     {/* Omission - Orange */}
                     <div className="flex flex-col items-center flex-1 h-full justify-end group relative">
                         <div className="text-xs font-bold text-slate-600 mb-2">{metrics.omissionCount}</div>
                         <div className="w-4 bg-orange-500 rounded-t relative hover:opacity-80 transition-opacity" style={{height: `${(metrics.omissionCount / 2000) * 80}%`}}></div>
                         <div className="text-[10px] text-slate-500 mt-2">漏选</div>
                     </div>
                     {/* Over - Yellow */}
                     <div className="flex flex-col items-center flex-1 h-full justify-end group relative">
                         <div className="text-xs font-bold text-slate-600 mb-2">{metrics.overCount}</div>
                         <div className="w-4 bg-yellow-500 rounded-t relative hover:opacity-80 transition-opacity" style={{height: `${(metrics.overCount / 2000) * 80}%`}}></div>
                         <div className="text-[10px] text-slate-500 mt-2">多选</div>
                     </div>
                     {/* Incorrect - Red */}
                     <div className="flex flex-col items-center flex-1 h-full justify-end group relative">
                         <div className="text-xs font-bold text-slate-600 mb-2">{metrics.incorrectCount}</div>
                         <div className="w-4 bg-red-500 rounded-t relative hover:opacity-80 transition-opacity" style={{height: `${(metrics.incorrectCount / 2000) * 80}%`}}></div>
                         <div className="text-[10px] text-slate-500 mt-2">不正确</div>
                     </div>
                 </div>
                 {/* Simple Legend */}
                 <div className="flex justify-center mt-2 space-x-3 text-[10px]">
                     <div className="flex items-center"><div className="w-1.5 h-1.5 bg-orange-500 mr-1 rounded-sm"></div>漏选</div>
                     <div className="flex items-center"><div className="w-1.5 h-1.5 bg-yellow-500 mr-1 rounded-sm"></div>多选</div>
                     <div className="flex items-center"><div className="w-1.5 h-1.5 bg-red-500 mr-1 rounded-sm"></div>不正确</div>
                 </div>
             </div>
         </div>
      </section>

      {/* --- DETAIL LIST --- */}
      <section className="bg-white rounded-lg border border-slate-200 shadow-sm flex flex-col">
          <div className="p-6 pb-0">
             <h2 className="text-lg font-bold text-slate-800 mb-4">会话明细列表</h2>

             {/* Filters */}
             <div className="bg-slate-50 p-4 rounded-lg border border-slate-100 grid grid-cols-5 gap-4 mb-6">
                 <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">日期</label>
                    <input 
                       type="date" 
                       value={filters.date}
                       onChange={(e) => { setFilters({...filters, date: e.target.value}); setPage(1); }}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">客服工号</label>
                    <input 
                       type="text" 
                       placeholder="输入工号"
                       value={filters.agentId}
                       onChange={(e) => { setFilters({...filters, agentId: e.target.value}); setPage(1); }}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">客户ID</label>
                    <input 
                       type="text" 
                       placeholder="输入客户ID"
                       value={filters.custId}
                       onChange={(e) => { setFilters({...filters, custId: e.target.value}); setPage(1); }}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">小结标签</label>
                    <input 
                       type="text" 
                       placeholder="搜索标签..."
                       value={filters.tag}
                       onChange={(e) => { setFilters({...filters, tag: e.target.value}); setPage(1); }}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                 </div>
                 <div className="relative" ref={dropdownRef}>
                    <label className="block text-xs font-medium text-slate-500 mb-1">修正类型 (多选)</label>
                    <button 
                       onClick={() => setIsTypeDropdownOpen(!isTypeDropdownOpen)}
                       className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm bg-white flex justify-between items-center focus:outline-none focus:ring-1 focus:ring-blue-500"
                    >
                       <span className={`truncate ${filters.correctionTypes.length ? 'text-slate-800' : 'text-slate-400'}`}>
                          {filters.correctionTypes.length > 0 ? filters.correctionTypes.map(t => t === 'OMISSION' ? '漏选' : t === 'OVER' ? '多选' : t === 'INCORRECT' ? '不正确' : '采纳').join(', ') : '选择类型'}
                       </span>
                       <ChevronDown size={14} className="text-slate-400 flex-shrink-0" />
                    </button>

                    {isTypeDropdownOpen && (
                        <div className="absolute top-full left-0 w-full mt-1 bg-white border border-slate-200 rounded shadow-lg z-10 p-2 space-y-1">
                           {['ADOPTED', 'OMISSION', 'OVER', 'INCORRECT'].map(type => {
                               const label = type === 'ADOPTED' ? '采纳' : type === 'OMISSION' ? '漏选' : type === 'OVER' ? '多选' : '不正确';
                               const isSelected = filters.correctionTypes.includes(type);
                               return (
                                   <div 
                                      key={type} 
                                      onClick={() => handleCorrectionTypeChange(type)}
                                      className="flex items-center px-2 py-1.5 hover:bg-slate-50 rounded cursor-pointer text-sm"
                                   >
                                      <div className={`w-3 h-3 border rounded mr-2 flex items-center justify-center ${isSelected ? 'bg-blue-600 border-blue-600' : 'border-slate-300'}`}>
                                          {isSelected && <div className="w-1.5 h-1.5 bg-white rounded-sm"></div>}
                                      </div>
                                      <span className="text-slate-700">{label}</span>
                                   </div>
                               );
                           })}
                        </div>
                    )}
                 </div>
             </div>
          </div>

          <div className="border-t border-slate-100">
              <table className="w-full text-sm text-left text-slate-600">
                  <thead className="bg-slate-50 text-slate-700 font-semibold">
                      <tr>
                          <th className="px-6 py-3 border-b whitespace-nowrap">会话ID</th>
                          <th className="px-6 py-3 border-b whitespace-nowrap">时间</th>
                          <th className="px-6 py-3 border-b whitespace-nowrap">客服工号</th>
                          <th className="px-6 py-3 border-b w-1/4">推荐标签</th>
                          <th className="px-6 py-3 border-b w-1/4">最终标签</th>
                          <th className="px-6 py-3 border-b whitespace-nowrap text-center">修正类型</th>
                          <th className="px-6 py-3 border-b">修正原因</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                      {paginatedList.map(row => (
                          <tr key={row.id} className="hover:bg-slate-50">
                              <td className="px-6 py-4 font-mono text-xs">{row.id}</td>
                              <td className="px-6 py-4 font-mono text-xs">{row.time}</td>
                              <td className="px-6 py-4">{row.agent}</td>
                              <td className="px-6 py-4">
                                  {renderTags(row.recSummary)}
                              </td>
                              <td className="px-6 py-4">
                                  {renderTags(row.finalSummary)}
                              </td>
                              <td className="px-6 py-4 text-center">
                                  <span className={`px-2 py-1 rounded text-xs border ${
                                      row.correctionType === '漏选' ? 'bg-orange-50 text-orange-600 border-orange-200' :
                                      row.correctionType === '多选' ? 'bg-yellow-50 text-yellow-600 border-yellow-200' :
                                      row.correctionType === '不正确' ? 'bg-red-50 text-red-600 border-red-200' :
                                      'bg-green-50 text-green-600 border-green-200'
                                  }`}>
                                      {row.correctionType}
                                  </span>
                              </td>
                              <td className="px-6 py-4 text-xs text-slate-500 italic">
                                  {row.reason}
                              </td>
                          </tr>
                      ))}
                      {paginatedList.length === 0 && (
                          <tr><td colSpan={7} className="text-center py-8 text-slate-400">无匹配数据</td></tr>
                      )}
                  </tbody>
              </table>
              <Pagination />
          </div>
      </section>
    </div>
  );
};

export default SummaryFeedback;
